cat <<'PY' > /tmp/helper.py
import subprocess, time, os, sys
class Tmux:
    def __init__(self, sess="probe", w=80, h=24, cmd="/workspace/executable", home="/tmp/fakehome"):
        self.sess=sess; self.home=home
        subprocess.run(["tmux","kill-session","-t",sess], capture_output=True)
        # ensure home exists clean maybe not
        env=os.environ.copy()
        # start server if needed with explicit env passed to new-session via -e (tmux 3.2 supports -e)
        args=["tmux","new-session","-d","-s",sess,"-x",str(w),"-y",str(h),"-e",f"HOME={home}","-e",f"XDG_CONFIG_HOME={home}/.config", cmd]
        r=subprocess.run(args, capture_output=True, text=True)
        if r.returncode!=0:
            print("new fail", r.stdout, r.stderr)
        time.sleep(0.6)
    def cap(self, esc=False):
        args=["tmux","capture-pane","-t",self.sess,"-p"]
        if esc: args.append("-e")
        return subprocess.run(args, capture_output=True, text=True).stdout
    def caplines(self, esc=False):
        s=self.cap(esc)
        for i,l in enumerate(s.splitlines()):
            print(f"{i:2d}: {repr(l)}")
    def send(self, *keys, delay=0.25):
        subprocess.run(["tmux","send-keys","-t",self.sess]+list(keys))
        time.sleep(delay)
    def send_text(self, text, delay_per=0.05, overall=0.3):
        # use send-keys -l ?
        for ch in text:
            if ch==" ":
                self.send("Space", delay=delay_per)
            else:
                # literal
                subprocess.run(["tmux","send-keys","-t",self.sess,"-l",ch])
                time.sleep(delay_per)
        time.sleep(overall)
    def kill(self):
        subprocess.run(["tmux","kill-session","-t",self.sess], capture_output=True)
    def alive(self):
        r=subprocess.run(["tmux","list-panes","-t",self.sess,"-F","#{pane_dead} #{pane_current_command}"], capture_output=True, text=True)
        return r.stdout.strip(), r.stderr.strip(), r.returncode
    def log(self):
        p=os.path.join(self.home,".config","thokr","log.csv")
        if os.path.exists(p):
            print(open(p).read())
        else:
            print("no log at",p)
            # search
            for root,dirs,files in os.walk(self.home):
                for f in files: print(os.path.join(root,f))
PY
rm -rf /tmp/fakehome && mkdir -p /tmp/fakehome
