import sys; sys.path.insert(0,"/tmp"); from helper import Tmux
import subprocess, time, re
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def top(prompt,w=80,h=24):
    cmd=f"/workspace/executable -p '{prompt}'"
    t=Tmux(w=w,h=h,cmd=cmd)
    lines=strip(t.cap(True)).splitlines()
    rows=[i for i,l in enumerate(lines) if l.strip()]
    t.kill(); subprocess.run(["tmux","kill-server"],capture_output=True); time.sleep(0.12)
    return rows[0] if rows else None, len(rows)
def inferH(prompt,label,w=80):
    Hs=set(range(0,40))
    for h in [24,25,20,21]:
        y,n=top(prompt,w=w,h=h)
        s={H for H in range(40) if (h-H)//2==y}
        Hs&=s
    print(label,f"w={w} len={len(prompt)} => H {sorted(Hs)}")
for w, width in [(40,30),(30,20),(20,10),(100,90)]:
    for L in [width-1,width,width+1,2*width,2*width+1,3*width,3*width+1]:
        inferH('a'*L,f"a{L}",w=w)
# horizontal width inference for w small <10? margin?
for w in [5,8,10,11,12,15]:
    for L in [3,5,10]:
        try:
            y,n=top('a'*L,w=w,h=10)
            print(f"small w={w} L={L} top={y} vis={n}")
        except Exception as e:
            print(e)
