import sys; sys.path.insert(0,"/tmp"); from helper import Tmux
import subprocess, time, re
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def get_prompt(cmd,w=80,h=24):
    t=Tmux(w=w,h=h,cmd=cmd)
    txt=strip(t.cap(True))
    lines=[l.strip() for l in txt.splitlines() if l.strip()]
    # reconstruct: lines joined with ... need careful: wrapped lines may split at spaces. Captured lines strip.
    t.kill(); subprocess.run(["tmux","kill-server"],capture_output=True); time.sleep(0.15)
    return lines

for i in range(5):
    print("default", get_prompt("/workspace/executable"))
for i in range(3):
    print("w5", get_prompt("/workspace/executable -w 5"))
    print("w1", get_prompt("/workspace/executable -w 1"))
    print("w0", get_prompt("/workspace/executable -w 0"))
    print("w100", get_prompt("/workspace/executable -w 100"))
for lang in ["english","english1k","english10k"]:
    for i in range(2):
        print(lang, get_prompt(f"/workspace/executable -w 20 -l {lang}"))
for f in [1,2,4,0]:
    print(f"f{f}", get_prompt(f"/workspace/executable -f {f}"))
