import sys; sys.path.insert(0,"/tmp"); from helper import Tmux
import subprocess,time,re,os,shutil
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def run_seq(prompt, seq, home="/tmp/fakehome2"):
    """seq list of (key, delay_after) key can be char or tmux name '<BS>' etc"""
    if os.path.exists(home): shutil.rmtree(home)
    os.makedirs(home, exist_ok=True)
    cmd=f"/workspace/executable -p '{prompt}'"
    t=Tmux(cmd=cmd,home=home)
    for key,delay in seq:
        if key==" ":
            t.send("Space",delay=0)
        elif key=="<BS>":
            t.send("BSpace",delay=0)
        elif key.startswith("<"):
            t.send(key[1:-1],delay=0)
        else:
            subprocess.run(["tmux","send-keys","-t",t.sess,"-l",key])
        time.sleep(delay)
    time.sleep(0.5)
    cap=strip(t.cap(True))
    print(f"prompt={prompt!r} seq={[k for k,d in seq]} delays={[d for k,d in seq]}")
    for l in cap.splitlines():
        if "wpm" in l and "acc" in l: print("SUMMARY",l.strip())
        if "│wpm" in l: print("TOP",l.strip()[:20])
    # x max line 18
    lines=cap.splitlines()
    if len(lines)>18: print("X",lines[18].strip())
    print("GRAPH:")
    for i,l in enumerate(lines):
        if l.strip() and i>=2 and i<=16: print(i,repr(l.rstrip()))
    t.log()
    try: t.send("Escape",delay=0.2)
    except: pass
    t.kill(); subprocess.run(["tmux","kill-server"],capture_output=True); time.sleep(0.12)
    return cap

def seq_from_typed(typed, delays):
    # delays list length = typed-1 intervals or all
    seq=[]
    for i,ch in enumerate(typed):
        d=delays[i] if i < len(delays) else 0
        seq.append((ch,d))
    return seq
