import pty, os, subprocess, time, select, sys, tty, termios, struct, fcntl, signal

def set_winsize(fd, rows=24, cols=80):
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

def run(args, inputs=[], wait=0.5, rows=24, cols=80, env_extra=None):
    pid, fd = pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"
        os.environ["HOME"]="/tmp/ptyhome"
        if env_extra: os.environ.update(env_extra)
        os.execv("/workspace/executable", ["/workspace/executable"]+args)
    set_winsize(fd,rows,cols)
    out=b""
    def drain(timeout=0.5):
        nonlocal out
        end=time.time()+timeout
        data=b""
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.05)
            if fd in r:
                try:
                    chunk=os.read(fd,65536)
                except OSError as e:
                    break
                if not chunk: break
                data+=chunk; out+=chunk
        return data
    initial=drain(wait)
    print("INITIAL bytes",len(initial),repr(initial))
    for label,data,delay in inputs:
        print("SEND",label,repr(data))
        os.write(fd,data)
        d=drain(delay)
        print(" -> bytes",len(d),repr(d))
    # check process status nonblocking
    wpid,status=os.waitpid(pid,os.WNOHANG)
    print("waitpid",wpid,status, "exit", os.waitstatus_to_exitcode(status) if wpid else None)
    if wpid==0:
        os.kill(pid, signal.SIGKILL); os.waitpid(pid,0)
    os.close(fd)
    return out

