import pty,os,time,select,fcntl,termios,struct,signal,re,shutil
def run(wait_before, mode):
    shutil.rmtree("/tmp/ptyhome",ignore_errors=True); os.makedirs("/tmp/ptyhome")
    pid,fd=pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]="/tmp/ptyhome"
        os.execv("/workspace/executable",["/workspace/executable","-p","ab"])
    fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,0,0))
    time.sleep(wait_before)
    # drain available
    out=b""
    def drain(timeout=0.02):
        nonlocal out
        end=time.time()+timeout
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.005)
            if fd in r:
                try:d=os.read(fd,65536)
                except:break
                out+=d
    drain()
    t0=time.time()
    if mode=="paste": os.write(fd,b"ab")
    elif mode=="separate001":
        os.write(fd,b"a"); time.sleep(0.01); os.write(fd,b"b")
    elif mode=="separate005":
        os.write(fd,b"a"); time.sleep(0.05); os.write(fd,b"b")
    elif mode=="separate02":
        os.write(fd,b"a"); time.sleep(0.2); os.write(fd,b"b")
    drain(0.5)
    log=""
    try: log=open("/tmp/ptyhome/.config/thokr/log.csv").read().splitlines()[-1]
    except Exception as e: log=str(e)
    print(mode,wait_before,"log",log)
    try:os.kill(pid,signal.SIGKILL);os.waitpid(pid,0)
    except:pass
    os.close(fd)
for mode in ["paste","separate001","separate005","separate02"]:
    for w in [0.3,0.37,0.62]:
        run(w,mode)
PY
