{"command":"cat <<'PY' > /tmp/pty_threshold.py
import pty,os,time,select,fcntl,termios,struct,signal,shutil
def run(delay,prompt="ab"):
    shutil.rmtree("/tmp/ptyhome",ignore_errors=True); os.makedirs("/tmp/ptyhome")
    pid,fd=pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]="/tmp/ptyhome"
        os.execv("/workspace/executable",["/workspace/executable","-p",prompt])
    fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,0,0)); time.sleep(0.3)
    # drain
    while select.select([fd],[],[],0)[0]:
        try: os.read(fd,65536)
        except:break
    chars=prompt.encode()
    for i,ch in enumerate(chars):
        os.write(fd,bytes([ch]))
        if i<len(chars)-1: time.sleep(delay)
    time.sleep(0.4)
    while select.select([fd],[],[],0)[0]:
        try: os.read(fd,65536)
        except:break
    try: log=open("/tmp/ptyhome/.config/thokr/log.csv").read().splitlines()[-1]
    except Exception as e: log=str(e)
    print(f"delay={delay*1000:.1f}ms prompt={prompt} -> {log}")
    try:os.kill(pid,signal.SIGKILL);os.waitpid(pid,0)
    except:pass
    os.close(fd)
for d in [0,0.0005,0.001,0.002,0.003,0.004,0.005,0.007,0.009,0.012]:
    run(d,"ab")
    run(d,"aaaaaaaaaa")
