import pty,os,time,select,fcntl,termios,struct,signal,shutil
def run(typed,secs=2,delay=0):
    shutil.rmtree("/tmp/ptyhome",ignore_errors=True); os.makedirs("/tmp/ptyhome")
    pid,fd=pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"; os.environ["HOME"]="/tmp/ptyhome"
        os.execv("/workspace/executable",["/workspace/executable","-p","hello world","-s",str(secs)])
    fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,0,0)); time.sleep(0.3)
    while select.select([fd],[],[],0)[0]: os.read(fd,65536)
    if delay==0: os.write(fd,typed.encode())
    else:
        for ch in typed: os.write(fd,ch.encode()); time.sleep(delay)
    time.sleep(secs+1)
    out=b""
    while select.select([fd],[],[],0)[0]: out+=os.read(fd,65536)
    try: log=open("/tmp/ptyhome/.config/thokr/log.csv").read()
    except Exception as e: log=str(e)
    print("typed",typed,"delay",delay,"log",log)
    try:os.kill(pid,signal.SIGKILL);os.waitpid(pid,0)
    except:pass
    os.close(fd)
run("h")
run("hell")
run("hell",delay=0.01)
run("hello world")
