use std::ffi::{OsStr, OsString};
use std::io::Write;
use std::os::unix::ffi::OsStrExt;
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SupportedLanguage {
    English,
    English1k,
    English10k,
}

#[derive(Debug, Clone)]
pub struct Args {
    pub number_of_words: u64,
    pub supported_language: SupportedLanguage,
    pub prompt: Option<String>,
    pub number_of_secs: Option<u64>,
    pub full_sentences: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Opt {
    FullSentences,
    SupportedLanguage,
    Prompt,
    NumberOfSecs,
    NumberOfWords,
}

impl Opt {
    fn canonical(self) -> &'static str {
        match self {
            Opt::FullSentences => "--full-sentences <NUMBER_OF_SENTENCES>",
            Opt::SupportedLanguage => "--supported-language <SUPPORTED_LANGUAGE>",
            Opt::Prompt => "--prompt <PROMPT>",
            Opt::NumberOfSecs => "--number-of-secs <NUMBER_OF_SECS>",
            Opt::NumberOfWords => "--number-of-words <NUMBER_OF_WORDS>",
        }
    }
    fn long(self) -> &'static str {
        match self {
            Opt::FullSentences => "full-sentences",
            Opt::SupportedLanguage => "supported-language",
            Opt::Prompt => "prompt",
            Opt::NumberOfSecs => "number-of-secs",
            Opt::NumberOfWords => "number-of-words",
        }
    }
    fn from_long(s: &str) -> Option<Self> {
        match s {
            "full-sentences" => Some(Opt::FullSentences),
            "supported-language" => Some(Opt::SupportedLanguage),
            "prompt" => Some(Opt::Prompt),
            "number-of-secs" => Some(Opt::NumberOfSecs),
            "number-of-words" => Some(Opt::NumberOfWords),
            _ => None,
        }
    }
    fn from_short(c: char) -> Option<Self> {
        match c {
            'f' => Some(Opt::FullSentences),
            'l' => Some(Opt::SupportedLanguage),
            'p' => Some(Opt::Prompt),
            's' => Some(Opt::NumberOfSecs),
            'w' => Some(Opt::NumberOfWords),
            _ => None,
        }
    }
}

#[derive(Debug)]
struct Occurrence {
    opt: Opt,
    value: Option<OsString>,
}

struct Parser {
    bin: String,
    display: String,
    occurrences: Vec<Occurrence>,
}

fn exit_with(code: i32, text: &str, to_stderr: bool) -> ! {
    if to_stderr {
        let _ = std::io::stderr().write_all(text.as_bytes());
        let _ = std::io::stderr().flush();
    } else {
        let _ = std::io::stdout().write_all(text.as_bytes());
        let _ = std::io::stdout().flush();
    }
    std::process::exit(code)
}

pub fn app_names(argv0: Option<OsString>) -> (String, String) {
    let mut bin: Option<String> = None;
    if let Some(a0) = argv0 {
        if let Some(s) = a0.to_str() {
            if let Some(file) = Path::new(s).file_name() {
                if let Some(file_str) = file.to_str() {
                    if !file_str.is_empty() {
                        bin = Some(file_str.to_owned());
                    }
                }
            }
        }
    }
    let bin = bin.unwrap_or_else(|| "thokr".to_owned());
    let display = if bin.contains(' ') {
        bin.replace(' ', "-")
    } else {
        "thokr".to_owned()
    };
    (bin, display)
}

impl Parser {
    fn help_text(&self) -> String {
        format!(
            "{} 0.4.1\nsleek typing tui with visualized results and historical logging\n\nUSAGE:\n    {} [OPTIONS]\n\nOPTIONS:\n    -f, --full-sentences <NUMBER_OF_SENTENCES>\n            number of sentences to use in test\n\n    -h, --help\n            Print help information\n\n    -l, --supported-language <SUPPORTED_LANGUAGE>\n            language to pull words from [default: english] [possible values: english, english1k,\n            english10k]\n\n    -p, --prompt <PROMPT>\n            custom prompt to use\n\n    -s, --number-of-secs <NUMBER_OF_SECS>\n            number of seconds to run test\n\n    -V, --version\n            Print version information\n\n    -w, --number-of-words <NUMBER_OF_WORDS>\n            number of words to use in test [default: 15]\n",
            self.display, self.bin
        )
    }

    fn print_help(&self) -> ! {
        exit_with(0, &self.help_text(), false)
    }

    fn print_version(&self) -> ! {
        exit_with(0, &format!("{} 0.4.1\n", self.display), false)
    }

    fn err(&self, text: String) -> ! {
        exit_with(2, &text, true)
    }

    fn distinct_opts(&self) -> Vec<Opt> {
        let mut out: Vec<Opt> = Vec::new();
        for occ in &self.occurrences {
            if !out.contains(&occ.opt) {
                out.push(occ.opt);
            }
        }
        out
    }

    fn usage_context(&self, suggestion: Option<Suggestion>) -> String {
        let mut parts: Vec<String> = self
            .distinct_opts()
            .iter()
            .map(|o| o.canonical().to_owned())
            .collect();
        if let Some(sug) = suggestion {
            let s = match sug {
                Suggestion::Opt(o) => {
                    if self.distinct_opts().contains(&o) {
                        None
                    } else {
                        Some(o.canonical().to_owned())
                    }
                }
                Suggestion::Help => Some("--help".to_owned()),
                Suggestion::Version => Some("--version".to_owned()),
            };
            if let Some(s) = s {
                parts.push(s);
            }
        }
        if parts.is_empty() {
            " [OPTIONS]".to_owned()
        } else {
            format!(" {}", parts.join(" "))
        }
    }

    fn usage_block(&self, suggestion: Option<Suggestion>) -> String {
        format!("USAGE:\n    {}{}", self.bin, self.usage_context(suggestion))
    }

    fn footer(&self) -> &'static str {
        "\n\nFor more information try --help\n"
    }

    fn unknown_positional(&self, arg: &str) -> ! {
        let mut s = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            arg
        );
        if arg.starts_with('-') {
            s.push_str(&format!(
                "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
                arg, arg
            ));
        }
        s.push_str(&format!("\n{}\n", self.usage_block(None)));
        // usage_block above uses context; positional errors always use [OPTIONS].
        // Rebuild to guarantee that exact shape.
        let mut s = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            arg
        );
        if arg.starts_with('-') {
            s.push_str(&format!(
                "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
                arg, arg
            ));
        }
        s.push_str(&format!("\nUSAGE:\n    {} [OPTIONS]", self.bin));
        s.push_str(self.footer());
        self.err(s)
    }

    fn unknown_short(&self, c: char) -> ! {
        let a = format!("-{}", c);
        self.err(format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n\nUSAGE:\n    {} [OPTIONS]{}",
            a, a, a, self.bin, self.footer()
        ))
    }

    fn unknown_long(&self, display: &str, name_for_suggestion: &str) -> ! {
        let suggestion = suggestion_for_long(name_for_suggestion);
        let mut s = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            display
        );
        if let Some(sug) = suggestion {
            s.push_str(&format!("\n\tDid you mean '--{}'?\n", sug.long_name()));
        }
        s.push_str(&format!(
            "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n\n{}",
            display,
            display,
            self.usage_block(suggestion)
        ));
        s.push_str(self.footer());
        self.err(s)
    }

    fn unexpected_value_for_flag(&self, flag: &str, value_with_eq: &str) -> ! {
        // Exactly as clap renders this error: no "USAGE:" label.
        self.err(format!(
            "error: The value '{}' was provided to '{}' but it wasn't expecting any more values\n\n{}{}{}",
            value_with_eq,
            flag,
            self.bin,
            self.usage_context(None),
            self.footer()
        ))
    }

    fn missing_value(&self, opt: Opt) -> ! {
        let mut s = format!(
            "error: The argument '{}' requires a value but none was supplied\n",
            opt.canonical()
        );
        if opt == Opt::SupportedLanguage {
            s.push_str("\t[possible values: english, english1k, english10k]\n");
        }
        s.push_str(&format!("\nUSAGE:\n    {} [OPTIONS]", self.bin));
        s.push_str(self.footer());
        self.err(s)
    }

    fn multiple_occurrence(&self, opt: Opt) -> ! {
        self.err(format!(
            "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} [OPTIONS]{}",
            opt.canonical(),
            self.bin,
            self.footer()
        ))
    }

    fn invalid_utf8(&self) -> ! {
        self.err(format!(
            "error: Invalid UTF-8 was detected in one or more arguments\n\nUSAGE:\n    {} [OPTIONS]{}",
            self.bin,
            self.footer()
        ))
    }

    fn invalid_numeric(&self, opt: Opt, value: &str, parse_err: &std::num::ParseIntError) -> ! {
        self.err(format!(
            "error: Invalid value \"{}\" for '{}': {}\n\nFor more information try --help\n",
            value,
            opt.canonical(),
            parse_err
        ))
    }

    fn invalid_language(&self, value: &str) -> ! {
        let sug = suggestion_for_value(value, &["english", "english1k", "english10k"]);
        let mut s = format!(
            "error: \"{}\" isn't a valid value for '{}'\n\t[possible values: english, english1k, english10k]\n",
            value,
            Opt::SupportedLanguage.canonical()
        );
        if let Some(v) = sug {
            s.push_str(&format!("\n\tDid you mean \"{}\"?\n", v));
        }
        let parts: Vec<String> = self
            .distinct_opts()
            .iter()
            .map(|o| o.canonical().to_owned())
            .collect();
        s.push_str(&format!("\nUSAGE:\n    {} {}", self.bin, parts.join(" ")));
        s.push_str(self.footer());
        self.err(s)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Suggestion {
    Opt(Opt),
    Help,
    Version,
}

impl Suggestion {
    fn long_name(self) -> &'static str {
        match self {
            Suggestion::Opt(o) => o.long(),
            Suggestion::Help => "help",
            Suggestion::Version => "version",
        }
    }
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    if a == b {
        return 1.0;
    }
    let match_distance = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_matched = vec![false; a.len()];
    let mut b_matched = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(match_distance);
        let end = (i + match_distance + 1).min(b.len());
        for j in start..end {
            if !b_matched[j] && a[i] == b[j] {
                a_matched[i] = true;
                b_matched[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if a_matched[i] {
            while !b_matched[k] {
                k += 1;
            }
            if a[i] != b[k] {
                transpositions += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (transpositions as f64) / 2.0) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let prefix = a
            .chars()
            .zip(b.chars())
            .take(4)
            .take_while(|(x, y)| x == y)
            .count();
        j + (prefix as f64 * 0.1 * (1.0 - j))
    } else {
        j
    }
}

fn suggestion_for_value<'a>(value: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<(f64, &'a str)> = None;
    for &cand in candidates {
        let conf = jaro_winkler(value, cand);
        if conf > 0.8 {
            if best.map_or(true, |(bc, _)| conf > bc) {
                best = Some((conf, cand));
            }
        }
    }
    best.map(|(_, c)| c)
}

fn suggestion_for_long(name: &str) -> Option<Suggestion> {
    // The reference reports --number-of-secs for essentially every
    // unknown "--number-of-*" flag whose similarity to it clears the
    // threshold, even when --number-of-words is textually closer.
    if name.starts_with("number-of-") && jaro_winkler(name, "number-of-secs") > 0.8 {
        return Some(Suggestion::Opt(Opt::NumberOfSecs));
    }
    let candidates: [(&str, Suggestion); 7] = [
        ("full-sentences", Suggestion::Opt(Opt::FullSentences)),
        ("help", Suggestion::Help),
        (
            "supported-language",
            Suggestion::Opt(Opt::SupportedLanguage),
        ),
        ("prompt", Suggestion::Opt(Opt::Prompt)),
        ("number-of-secs", Suggestion::Opt(Opt::NumberOfSecs)),
        ("version", Suggestion::Version),
        ("number-of-words", Suggestion::Opt(Opt::NumberOfWords)),
    ];
    let mut best: Option<(f64, Suggestion)> = None;
    for (cand, sug) in candidates {
        let conf = jaro_winkler(name, cand);
        if conf > 0.8 && best.map_or(true, |(bc, _)| conf > bc) {
            best = Some((conf, sug));
        }
    }
    best.map(|(_, s)| s)
}

enum FlagKind {
    Opt(Opt, Option<OsString>), // Some(attached value) or None (needs separate)
}

impl Parser {
    /// Classify and (where it is an error / help / version) act on a
    /// flag-like token.  `pending` is the option currently awaiting a
    /// separate value, if any.  Returns the classified option flag.
    fn classify_flag(&self, token: &OsStr, pending: Option<Opt>) -> FlagKind {
        let bytes = token.as_bytes();
        if bytes.starts_with(b"--") {
            // Long flag.
            let eq = bytes.iter().position(|&b| b == b'=');
            let name_part_end = eq.unwrap_or(bytes.len());
            let display = String::from_utf8_lossy(&bytes[..name_part_end]).into_owned();
            let name = String::from_utf8_lossy(&bytes[2..name_part_end]).into_owned();
            match name.as_str() {
                "help" => {
                    if let Some(eqpos) = eq {
                        let with_eq = String::from_utf8_lossy(&bytes[eqpos..]).into_owned();
                        self.unexpected_value_for_flag("--help", &with_eq)
                    }
                    self.print_help()
                }
                "version" => {
                    if let Some(eqpos) = eq {
                        let with_eq = String::from_utf8_lossy(&bytes[eqpos..]).into_owned();
                        self.unexpected_value_for_flag("--version", &with_eq)
                    }
                    self.print_version()
                }
                _ => {
                    if let Some(opt) = Opt::from_long(&name) {
                        if let Some(p) = pending {
                            if p != opt {
                                self.missing_value(p);
                            }
                        }
                        let attached = eq.map(|eqpos| OsString::from(OsStr::from_bytes(&bytes[eqpos + 1..])));
                        // We need to reconstruct an OsString from raw bytes.
                        let attached = attached.map(|_| {
                            use std::os::unix::ffi::OsStringExt;
                            OsString::from_vec(bytes[eq.unwrap() + 1..].to_vec())
                        });
                        FlagKind::Opt(opt, attached)
                    } else {
                        self.unknown_long(&display, &name)
                    }
                }
            }
        } else {
            // Short cluster: first character decides.
            let lossy = String::from_utf8_lossy(bytes).into_owned();
            let first = lossy.chars().nth(1).unwrap_or('\0');
            if first == 'h' {
                self.print_help();
            }
            if first == 'V' {
                self.print_version();
            }
            if let Some(opt) = Opt::from_short(first) {
                if let Some(p) = pending {
                    if p != opt {
                        self.missing_value(p);
                    }
                }
                // Rest of the raw token after "-X".
                let rest = &bytes[2..];
                let attached = if rest.is_empty() {
                    None
                } else {
                    let value_bytes = if rest[0] == b'=' { &rest[1..] } else { rest };
                    use std::os::unix::ffi::OsStringExt;
                    Some(OsString::from_vec(value_bytes.to_vec()))
                };
                FlagKind::Opt(opt, attached)
            } else {
                self.unknown_short(first)
            }
        }
    }

    fn register(&mut self, kind: FlagKind, pending: &mut Option<usize>) {
        match kind {
            FlagKind::Opt(opt, attached) => {
                self.occurrences.push(Occurrence {
                    opt,
                    value: attached.clone(),
                });
                if attached.is_none() {
                    *pending = Some(self.occurrences.len() - 1);
                } else {
                    *pending = None;
                }
            }
        }
    }
}

pub fn parse() -> Args {
    let mut argv = std::env::args_os();
    let argv0 = argv.next();
    let (bin, display) = app_names(argv0);
    let mut parser = Parser {
        bin,
        display,
        occurrences: Vec::new(),
    };

    let mut pending: Option<usize> = None;
    let mut hanging_pending: Option<usize> = None;
    let mut trailing = false;

    for token in argv {
        let bytes = token.as_bytes().to_vec();
        if trailing {
            parser.unknown_positional(&String::from_utf8_lossy(&bytes));
        }
        if bytes == b"--" {
            trailing = true;
            if let Some(p) = pending.take() {
                hanging_pending = Some(p);
            }
            continue;
        }
        if let Some(pidx) = pending {
            let pending_opt = parser.occurrences[pidx].opt;
            let is_value = bytes == b"-" || !bytes.starts_with(b"-");
            if is_value {
                parser.occurrences[pidx].value = Some(token.clone());
                pending = None;
                continue;
            }
            // Flag-like token while awaiting a value.
            let kind = parser.classify_flag(&token, Some(pending_opt));
            // If classify returned an option, it is either the same
            // option (the previous occurrence stays valueless) — the
            // distinct-option case already raised a missing-value
            // error inside classify_flag.
            parser.register(kind, &mut pending);
            continue;
        }
        // Not awaiting a value.
        if bytes == b"-" || !bytes.starts_with(b"-") {
            parser.unknown_positional(&String::from_utf8_lossy(&bytes));
        }
        let kind = parser.classify_flag(&token, None);
        parser.register(kind, &mut pending);
    }

    // End of input: an option still awaiting its (only) value is a
    // missing-value error, which takes precedence over validation of
    // other arguments.  A repeated option awaiting a value goes
    // through normal validation (values first, then multiple use).
    let unfinished = pending.or(hanging_pending);
    if let Some(idx) = unfinished {
        let opt = parser.occurrences[idx].opt;
        let total = parser
            .occurrences
            .iter()
            .filter(|o| o.opt == opt)
            .count();
        if total == 1 {
            parser.missing_value(opt);
        }
    }

    // Validation, in order of each option's first appearance.
    let distinct = parser.distinct_opts();
    let mut number_of_words: u64 = 15;
    let mut supported_language = SupportedLanguage::English;
    let mut prompt: Option<String> = None;
    let mut number_of_secs: Option<u64> = None;
    let mut full_sentences: Option<u64> = None;

    for opt in distinct {
        let occs: Vec<&Occurrence> = parser
            .occurrences
            .iter()
            .filter(|o| o.opt == opt)
            .collect();
        for occ in &occs {
            if let Some(value_os) = &occ.value {
                let Some(value) = value_os.to_str() else {
                    parser.invalid_utf8();
                };
                match opt {
                    Opt::NumberOfWords | Opt::NumberOfSecs | Opt::FullSentences => {
                        match value.parse::<u64>() {
                            Ok(n) => match opt {
                                Opt::NumberOfWords => number_of_words = n,
                                Opt::NumberOfSecs => number_of_secs = Some(n),
                                _ => full_sentences = Some(n),
                            },
                            Err(e) => parser.invalid_numeric(opt, value, &e),
                        }
                    }
                    Opt::SupportedLanguage => match value {
                        "english" => supported_language = SupportedLanguage::English,
                        "english1k" => supported_language = SupportedLanguage::English1k,
                        "english10k" => supported_language = SupportedLanguage::English10k,
                        _ => parser.invalid_language(value),
                    },
                    Opt::Prompt => {
                        prompt = Some(value.to_owned());
                    }
                }
            }
        }
        if occs.len() > 1 {
            parser.multiple_occurrence(opt);
        }
    }

    Args {
        number_of_words,
        supported_language,
        prompt,
        number_of_secs,
        full_sentences,
    }
}
RS
"}

actions.command:
cat <<'RS' > src/cli.rs
use std::ffi::{OsStr, OsString};
use std::io::Write;
use std::os::unix::ffi::OsStrExt;
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SupportedLanguage {
    English,
    English1k,
    English10k,
}

#[derive(Debug, Clone)]
pub struct Args {
    pub number_of_words: u64,
    pub supported_language: SupportedLanguage,
    pub prompt: Option<String>,
    pub number_of_secs: Option<u64>,
    pub full_sentences: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Opt {
    FullSentences,
    SupportedLanguage,
    Prompt,
    NumberOfSecs,
    NumberOfWords,
}

impl Opt {
    fn canonical(self) -> &'static str {
        match self {
            Opt::FullSentences => "--full-sentences <NUMBER_OF_SENTENCES>",
            Opt::SupportedLanguage => "--supported-language <SUPPORTED_LANGUAGE>",
            Opt::Prompt => "--prompt <PROMPT>",
            Opt::NumberOfSecs => "--number-of-secs <NUMBER_OF_SECS>",
            Opt::NumberOfWords => "--number-of-words <NUMBER_OF_WORDS>",
        }
    }
    fn long(self) -> &'static str {
        match self {
            Opt::FullSentences => "full-sentences",
            Opt::SupportedLanguage => "supported-language",
            Opt::Prompt => "prompt",
            Opt::NumberOfSecs => "number-of-secs",
            Opt::NumberOfWords => "number-of-words",
        }
    }
    fn from_long(s: &str) -> Option<Self> {
        match s {
            "full-sentences" => Some(Opt::FullSentences),
            "supported-language" => Some(Opt::SupportedLanguage),
            "prompt" => Some(Opt::Prompt),
            "number-of-secs" => Some(Opt::NumberOfSecs),
            "number-of-words" => Some(Opt::NumberOfWords),
            _ => None,
        }
    }
    fn from_short(c: char) -> Option<Self> {
        match c {
            'f' => Some(Opt::FullSentences),
            'l' => Some(Opt::SupportedLanguage),
            'p' => Some(Opt::Prompt),
            's' => Some(Opt::NumberOfSecs),
            'w' => Some(Opt::NumberOfWords),
            _ => None,
        }
    }
}

#[derive(Debug)]
struct Occurrence {
    opt: Opt,
    value: Option<OsString>,
}

struct Parser {
    bin: String,
    display: String,
    occurrences: Vec<Occurrence>,
}

fn exit_with(code: i32, text: &str, to_stderr: bool) -> ! {
    if to_stderr {
        let _ = std::io::stderr().write_all(text.as_bytes());
        let _ = std::io::stderr().flush();
    } else {
        let _ = std::io::stdout().write_all(text.as_bytes());
        let _ = std::io::stdout().flush();
    }
    std::process::exit(code)
}

pub fn app_names(argv0: Option<OsString>) -> (String, String) {
    let mut bin: Option<String> = None;
    if let Some(a0) = argv0 {
        if let Some(s) = a0.to_str() {
            if let Some(file) = Path::new(s).file_name() {
                if let Some(file_str) = file.to_str() {
                    if !file_str.is_empty() {
                        bin = Some(file_str.to_owned());
                    }
                }
            }
        }
    }
    let bin = bin.unwrap_or_else(|| "thokr".to_owned());
    let display = if bin.contains(' ') {
        bin.replace(' ', "-")
    } else {
        "thokr".to_owned()
    };
    (bin, display)
}

impl Parser {
    fn help_text(&self) -> String {
        format!(
            "{} 0.4.1\nsleek typing tui with visualized results and historical logging\n\nUSAGE:\n    {} [OPTIONS]\n\nOPTIONS:\n    -f, --full-sentences <NUMBER_OF_SENTENCES>\n            number of sentences to use in test\n\n    -h, --help\n            Print help information\n\n    -l, --supported-language <SUPPORTED_LANGUAGE>\n            language to pull words from [default: english] [possible values: english, english1k,\n            english10k]\n\n    -p, --prompt <PROMPT>\n            custom prompt to use\n\n    -s, --number-of-secs <NUMBER_OF_SECS>\n            number of seconds to run test\n\n    -V, --version\n            Print version information\n\n    -w, --number-of-words <NUMBER_OF_WORDS>\n            number of words to use in test [default: 15]\n",
            self.display, self.bin
        )
    }

    fn print_help(&self) -> ! {
        exit_with(0, &self.help_text(), false)
    }

    fn print_version(&self) -> ! {
        exit_with(0, &format!("{} 0.4.1\n", self.display), false)
    }

    fn err(&self, text: String) -> ! {
        exit_with(2, &text, true)
    }

    fn distinct_opts(&self) -> Vec<Opt> {
        let mut out: Vec<Opt> = Vec::new();
        for occ in &self.occurrences {
            if !out.contains(&occ.opt) {
                out.push(occ.opt);
            }
        }
        out
    }

    fn usage_context(&self, suggestion: Option<Suggestion>) -> String {
        let mut parts: Vec<String> = self
            .distinct_opts()
            .iter()
            .map(|o| o.canonical().to_owned())
            .collect();
        if let Some(sug) = suggestion {
            let s = match sug {
                Suggestion::Opt(o) => {
                    if self.distinct_opts().contains(&o) {
                        None
                    } else {
                        Some(o.canonical().to_owned())
                    }
                }
                Suggestion::Help => Some("--help".to_owned()),
                Suggestion::Version => Some("--version".to_owned()),
            };
            if let Some(s) = s {
                parts.push(s);
            }
        }
        if parts.is_empty() {
            " [OPTIONS]".to_owned()
        } else {
            format!(" {}", parts.join(" "))
        }
    }

    fn usage_block(&self, suggestion: Option<Suggestion>) -> String {
        format!("USAGE:\n    {}{}", self.bin, self.usage_context(suggestion))
    }

    fn footer(&self) -> &'static str {
        "\n\nFor more information try --help\n"
    }

    fn unknown_positional(&self, arg: &str) -> ! {
        let mut s = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            arg
        );
        if arg.starts_with('-') {
            s.push_str(&format!(
                "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
                arg, arg
            ));
        }
        s.push_str(&format!("\n{}\n", self.usage_block(None)));
        // usage_block above uses context; positional errors always use [OPTIONS].
        // Rebuild to guarantee that exact shape.
        let mut s = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            arg
        );
        if arg.starts_with('-') {
            s.push_str(&format!(
                "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
                arg, arg
            ));
        }
        s.push_str(&format!("\nUSAGE:\n    {} [OPTIONS]", self.bin));
        s.push_str(self.footer());
        self.err(s)
    }

    fn unknown_short(&self, c: char) -> ! {
        let a = format!("-{}", c);
        self.err(format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n\nUSAGE:\n    {} [OPTIONS]{}",
            a, a, a, self.bin, self.footer()
        ))
    }

    fn unknown_long(&self, display: &str, name_for_suggestion: &str) -> ! {
        let suggestion = suggestion_for_long(name_for_suggestion);
        let mut s = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            display
        );
        if let Some(sug) = suggestion {
            s.push_str(&format!("\n\tDid you mean '--{}'?\n", sug.long_name()));
        }
        s.push_str(&format!(
            "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n\n{}",
            display,
            display,
            self.usage_block(suggestion)
        ));
        s.push_str(self.footer());
        self.err(s)
    }

    fn unexpected_value_for_flag(&self, flag: &str, value_with_eq: &str) -> ! {
        // Exactly as clap renders this error: no "USAGE:" label.
        self.err(format!(
            "error: The value '{}' was provided to '{}' but it wasn't expecting any more values\n\n{}{}{}",
            value_with_eq,
            flag,
            self.bin,
            self.usage_context(None),
            self.footer()
        ))
    }

    fn missing_value(&self, opt: Opt) -> ! {
        let mut s = format!(
            "error: The argument '{}' requires a value but none was supplied\n",
            opt.canonical()
        );
        if opt == Opt::SupportedLanguage {
            s.push_str("\t[possible values: english, english1k, english10k]\n");
        }
        s.push_str(&format!("\nUSAGE:\n    {} [OPTIONS]", self.bin));
        s.push_str(self.footer());
        self.err(s)
    }

    fn multiple_occurrence(&self, opt: Opt) -> ! {
        self.err(format!(
            "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} [OPTIONS]{}",
            opt.canonical(),
            self.bin,
            self.footer()
        ))
    }

    fn invalid_utf8(&self) -> ! {
        self.err(format!(
            "error: Invalid UTF-8 was detected in one or more arguments\n\nUSAGE:\n    {} [OPTIONS]{}",
            self.bin,
            self.footer()
        ))
    }

    fn invalid_numeric(&self, opt: Opt, value: &str, parse_err: &std::num::ParseIntError) -> ! {
        self.err(format!(
            "error: Invalid value \"{}\" for '{}': {}\n\nFor more information try --help\n",
            value,
            opt.canonical(),
            parse_err
        ))
    }

    fn invalid_language(&self, value: &str) -> ! {
        let sug = suggestion_for_value(value, &["english", "english1k", "english10k"]);
        let mut s = format!(
            "error: \"{}\" isn't a valid value for '{}'\n\t[possible values: english, english1k, english10k]\n",
            value,
            Opt::SupportedLanguage.canonical()
        );
        if let Some(v) = sug {
            s.push_str(&format!("\n\tDid you mean \"{}\"?\n", v));
        }
        let parts: Vec<String> = self
            .distinct_opts()
            .iter()
            .map(|o| o.canonical().to_owned())
            .collect();
        s.push_str(&format!("\nUSAGE:\n    {} {}", self.bin, parts.join(" ")));
        s.push_str(self.footer());
        self.err(s)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Suggestion {
    Opt(Opt),
    Help,
    Version,
}

impl Suggestion {
    fn long_name(self) -> &'static str {
        match self {
            Suggestion::Opt(o) => o.long(),
            Suggestion::Help => "help",
            Suggestion::Version => "version",
        }
    }
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    if a == b {
        return 1.0;
    }
    let match_distance = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_matched = vec![false; a.len()];
    let mut b_matched = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(match_distance);
        let end = (i + match_distance + 1).min(b.len());
        for j in start..end {
            if !b_matched[j] && a[i] == b[j] {
                a_matched[i] = true;
                b_matched[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if a_matched[i] {
            while !b_matched[k] {
                k += 1;
            }
            if a[i] != b[k] {
                transpositions += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (transpositions as f64) / 2.0) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let prefix = a
            .chars()
            .zip(b.chars())
            .take(4)
            .take_while(|(x, y)| x == y)
            .count();
        j + (prefix as f64 * 0.1 * (1.0 - j))
    } else {
        j
    }
}

fn suggestion_for_value<'a>(value: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<(f64, &'a str)> = None;
    for &cand in candidates {
        let conf = jaro_winkler(value, cand);
        if conf > 0.8 {
            if best.map_or(true, |(bc, _)| conf > bc) {
                best = Some((conf, cand));
            }
        }
    }
    best.map(|(_, c)| c)
}

fn suggestion_for_long(name: &str) -> Option<Suggestion> {
    // The reference reports --number-of-secs for essentially every
    // unknown "--number-of-*" flag whose similarity to it clears the
    // threshold, even when --number-of-words is textually closer.
    if name.starts_with("number-of-") && jaro_winkler(name, "number-of-secs") > 0.8 {
        return Some(Suggestion::Opt(Opt::NumberOfSecs));
    }
    let candidates: [(&str, Suggestion); 7] = [
        ("full-sentences", Suggestion::Opt(Opt::FullSentences)),
        ("help", Suggestion::Help),
        (
            "supported-language",
            Suggestion::Opt(Opt::SupportedLanguage),
        ),
        ("prompt", Suggestion::Opt(Opt::Prompt)),
        ("number-of-secs", Suggestion::Opt(Opt::NumberOfSecs)),
        ("version", Suggestion::Version),
        ("number-of-words", Suggestion::Opt(Opt::NumberOfWords)),
    ];
    let mut best: Option<(f64, Suggestion)> = None;
    for (cand, sug) in candidates {
        let conf = jaro_winkler(name, cand);
        if conf > 0.8 && best.map_or(true, |(bc, _)| conf > bc) {
            best = Some((conf, sug));
        }
    }
    best.map(|(_, s)| s)
}

enum FlagKind {
    Opt(Opt, Option<OsString>), // Some(attached value) or None (needs separate)
}

impl Parser {
    /// Classify and (where it is an error / help / version) act on a
    /// flag-like token.  `pending` is the option currently awaiting a
    /// separate value, if any.  Returns the classified option flag.
    fn classify_flag(&self, token: &OsStr, pending: Option<Opt>) -> FlagKind {
        let bytes = token.as_bytes();
        if bytes.starts_with(b"--") {
            // Long flag.
            let eq = bytes.iter().position(|&b| b == b'=');
            let name_part_end = eq.unwrap_or(bytes.len());
            let display = String::from_utf8_lossy(&bytes[..name_part_end]).into_owned();
            let name = String::from_utf8_lossy(&bytes[2..name_part_end]).into_owned();
            match name.as_str() {
                "help" => {
                    if let Some(eqpos) = eq {
                        let with_eq = String::from_utf8_lossy(&bytes[eqpos..]).into_owned();
                        self.unexpected_value_for_flag("--help", &with_eq)
                    }
                    self.print_help()
                }
                "version" => {
                    if let Some(eqpos) = eq {
                        let with_eq = String::from_utf8_lossy(&bytes[eqpos..]).into_owned();
                        self.unexpected_value_for_flag("--version", &with_eq)
                    }
                    self.print_version()
                }
                _ => {
                    if let Some(opt) = Opt::from_long(&name) {
                        if let Some(p) = pending {
                            if p != opt {
                                self.missing_value(p);
                            }
                        }
                        let attached = eq.map(|eqpos| OsString::from(OsStr::from_bytes(&bytes[eqpos + 1..])));
                        // We need to reconstruct an OsString from raw bytes.
                        let attached = attached.map(|_| {
                            use std::os::unix::ffi::OsStringExt;
                            OsString::from_vec(bytes[eq.unwrap() + 1..].to_vec())
                        });
                        FlagKind::Opt(opt, attached)
                    } else {
                        self.unknown_long(&display, &name)
                    }
                }
            }
        } else {
            // Short cluster: first character decides.
            let lossy = String::from_utf8_lossy(bytes).into_owned();
            let first = lossy.chars().nth(1).unwrap_or('\0');
            if first == 'h' {
                self.print_help();
            }
            if first == 'V' {
                self.print_version();
            }
            if let Some(opt) = Opt::from_short(first) {
                if let Some(p) = pending {
                    if p != opt {
                        self.missing_value(p);
                    }
                }
                // Rest of the raw token after "-X".
                let rest = &bytes[2..];
                let attached = if rest.is_empty() {
                    None
                } else {
                    let value_bytes = if rest[0] == b'=' { &rest[1..] } else { rest };
                    use std::os::unix::ffi::OsStringExt;
                    Some(OsString::from_vec(value_bytes.to_vec()))
                };
                FlagKind::Opt(opt, attached)
            } else {
                self.unknown_short(first)
            }
        }
    }

    fn register(&mut self, kind: FlagKind, pending: &mut Option<usize>) {
        match kind {
            FlagKind::Opt(opt, attached) => {
                self.occurrences.push(Occurrence {
                    opt,
                    value: attached.clone(),
                });
                if attached.is_none() {
                    *pending = Some(self.occurrences.len() - 1);
                } else {
                    *pending = None;
                }
            }
        }
    }
}

pub fn parse() -> Args {
    let mut argv = std::env::args_os();
    let argv0 = argv.next();
    let (bin, display) = app_names(argv0);
    let mut parser = Parser {
        bin,
        display,
        occurrences: Vec::new(),
    };

    let mut pending: Option<usize> = None;
    let mut hanging_pending: Option<usize> = None;
    let mut trailing = false;

    for token in argv {
        let bytes = token.as_bytes().to_vec();
        if trailing {
            parser.unknown_positional(&String::from_utf8_lossy(&bytes));
        }
        if bytes == b"--" {
            trailing = true;
            if let Some(p) = pending.take() {
                hanging_pending = Some(p);
            }
            continue;
        }
        if let Some(pidx) = pending {
            let pending_opt = parser.occurrences[pidx].opt;
            let is_value = bytes == b"-" || !bytes.starts_with(b"-");
            if is_value {
                parser.occurrences[pidx].value = Some(token.clone());
                pending = None;
                continue;
            }
            // Flag-like token while awaiting a value.
            let kind = parser.classify_flag(&token, Some(pending_opt));
            // If classify returned an option, it is either the same
            // option (the previous occurrence stays valueless) — the
            // distinct-option case already raised a missing-value
            // error inside classify_flag.
            parser.register(kind, &mut pending);
            continue;
        }
        // Not awaiting a value.
        if bytes == b"-" || !bytes.starts_with(b"-") {
            parser.unknown_positional(&String::from_utf8_lossy(&bytes));
        }
        let kind = parser.classify_flag(&token, None);
        parser.register(kind, &mut pending);
    }

    // End of input: an option still awaiting its (only) value is a
    // missing-value error, which takes precedence over validation of
    // other arguments.  A repeated option awaiting a value goes
    // through normal validation (values first, then multiple use).
    let unfinished = pending.or(hanging_pending);
    if let Some(idx) = unfinished {
        let opt = parser.occurrences[idx].opt;
        let total = parser
            .occurrences
            .iter()
            .filter(|o| o.opt == opt)
            .count();
        if total == 1 {
            parser.missing_value(opt);
        }
    }

    // Validation, in order of each option's first appearance.
    let distinct = parser.distinct_opts();
    let mut number_of_words: u64 = 15;
    let mut supported_language = SupportedLanguage::English;
    let mut prompt: Option<String> = None;
    let mut number_of_secs: Option<u64> = None;
    let mut full_sentences: Option<u64> = None;

    for opt in distinct {
        let occs: Vec<&Occurrence> = parser
            .occurrences
            .iter()
            .filter(|o| o.opt == opt)
            .collect();
        for occ in &occs {
            if let Some(value_os) = &occ.value {
                let Some(value) = value_os.to_str() else {
                    parser.invalid_utf8();
                };
                match opt {
                    Opt::NumberOfWords | Opt::NumberOfSecs | Opt::FullSentences => {
                        match value.parse::<u64>() {
                            Ok(n) => match opt {
                                Opt::NumberOfWords => number_of_words = n,
                                Opt::NumberOfSecs => number_of_secs = Some(n),
                                _ => full_sentences = Some(n),
                            },
                            Err(e) => parser.invalid_numeric(opt, value, &e),
                        }
                    }
                    Opt::SupportedLanguage => match value {
                        "english" => supported_language = SupportedLanguage::English,
                        "english1k" => supported_language = SupportedLanguage::English1k,
                        "english10k" => supported_language = SupportedLanguage::English10k,
                        _ => parser.invalid_language(value),
                    },
                    Opt::Prompt => {
                        prompt = Some(value.to_owned());
                    }
                }
            }
        }
        if occs.len() > 1 {
            parser.multiple_occurrence(opt);
        }
    }

    Args {
        number_of_words,
        supported_language,
        prompt,
        number_of_secs,
        full_sentences,
    }
}
