const ENGLISH: &str = include_str!("data/english.txt");
const ENGLISH1K: &str = include_str!("data/english1k.txt");
const ENGLISH10K: &str = include_str!("data/english10k.txt");

/// A small, fast PRNG (xoshiro256++).  Seeded from the operating
/// system so that every run and every "new" test looks different.
pub struct Rng {
    state: [u64; 4],
}

impl Rng {
    pub fn new() -> Self {
        let mut seed_bytes = [0u8; 32];
        let mut filled = false;
        if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
            if f.read_exact(&mut seed_bytes).is_ok() {
                filled = true;
            }
        }
        if !filled {
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default();
            let mut x = (now.as_nanos() as u64) ^ ((std::process::id() as u64) << 32) ^ 0x9E3779B97F4A7C15;
            for b in seed_bytes.iter_mut() {
                // xorshift64*
                x ^= x >> 12;
                x ^= x << 25;
                x ^= x >> 27;
                *b = (x.wrapping_mul(0x2545F4914F6CDD1D) >> 56) as u8;
            }
        }
        let mut state = [0u64; 4];
        for i in 0..4 {
            state[i] = u64::from_le_bytes(seed_bytes[i * 8..i * 8 + 8].try_into().unwrap());
        }
        if state.iter().all(|&s| s == 0) {
            state[0] = 0x2545F4914F6CDD1D;
        }
        Rng { state }
    }

    fn next_u64(&mut self) -> u64 {
        let result = (self.state[0]
            .wrapping_add(self.state[3]))
        .rotate_left(23)
        .wrapping_add(self.state[0]);
        let t = self.state[1] << 17;
        self.state[2] ^= self.state[0];
        self.state[3] ^= self.state[1];
        self.state[1] ^= self.state[2];
        self.state[0] ^= self.state[3];
        self.state[2] ^= t;
        self.state[3] = self.state[3].rotate_left(45);
        result
    }

    /// Uniform value in `0..n` (n must be > 0), via Lemire's method.
    pub fn below(&mut self, n: usize) -> usize {
        if n <= 1 {
            return 0;
        }
        let n = n as u64;
        loop {
            let x = self.next_u64();
            let m = (x as u128).wrapping_mul(n as u128);
            let lo = m as u64;
            if lo < n {
                let threshold = n.wrapping_neg() % n;
                if lo < threshold {
                    continue;
                }
            }
            return (m >> 64) as usize;
        }
    }

    pub fn chance(&mut self, numerator: usize, denominator: usize) -> bool {
        self.below(denominator) < numerator
    }

    pub fn shuffle<T>(&mut self, items: &mut [T]) {
        if items.len() < 2 {
            return;
        }
        for i in (1..items.len()).rev() {
            let j = self.below(i + 1);
            items.swap(i, j);
        }
    }

    fn pick<'a, T>(&mut self, items: &'a [T]) -> &'a T {
        &items[self.below(items.len())]
    }
}

fn word_pool(language: SupportedLanguage) -> Vec<&'static str> {
    let text = match language {
        SupportedLanguage::English => ENGLISH,
        SupportedLanguage::English1k => ENGLISH1K,
        SupportedLanguage::English10k => ENGLISH10K,
    };
    text.lines().filter(|l| !l.is_empty()).collect()
}

pub fn generate_words(rng: &mut Rng, language: SupportedLanguage, count: u64) -> String {
    let mut pool = word_pool(language);
    rng.shuffle(&mut pool);
    let take = (count as usize).min(pool.len());
    pool[..take].join(" ")
}

