fn pluralize(word: &str) -> String {
    let bytes = word.as_bytes();
    if word.ends_with('y') {
        if let Some(&prev) = bytes.get(bytes.len().wrapping_sub(2)) {
            if !matches!(prev, b'a' | b'e' | b'i' | b'o' | b'u' | b'A' | b'E' | b'I' | b'O' | b'U') {
                return format!("{}ies", &word[..word.len() - 1]);
            }
        }
    }
    format!("{}s", word)
}

fn third_person(word: &str) -> String {
    pluralize(word)
}

fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        None => String::new(),
        Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
    }
}

fn noun_phrase(rng: &mut Rng, allow_article: bool, article: &str) -> (Vec<String>, bool) {
    let mut words: Vec<String> = Vec::new();
    if allow_article && rng.chance(3, 4) {
        words.push(article.to_owned());
    }
    let adjective_count = if rng.chance(1, 2) { 1 } else { 2 };
    for _ in 0..adjective_count {
        words.push((*rng.pick(ADJECTIVES)).to_owned());
    }
    let noun = *rng.pick(NOUNS);
    let plural = rng.chance(1, 2);
    if plural {
        words.push(pluralize(noun));
    } else {
        words.push(noun.to_owned());
    }
    (words, plural)
}

fn generate_sentence(rng: &mut Rng) -> String {
    let (subject, subject_plural) = noun_phrase(rng, true, "The");
    let adverb_count = if rng.chance(1, 2) { 1 } else { 2 };
    let adverbs_before = rng.chance(1, 2);
    let mut adverbs: Vec<String> = Vec::new();
    for _ in 0..adverb_count {
        adverbs.push((*rng.pick(ADVERBS)).to_owned());
    }
    let verb_base = *rng.pick(VERBS);
    let verb = if subject_plural {
        verb_base.to_owned()
    } else {
        third_person(verb_base)
    };

    let mut words: Vec<String> = subject;
    if adverbs_before {
        words.extend(adverbs.iter().cloned());
        words.push(verb);
    } else {
        words.push(verb);
        words.extend(adverbs.iter().cloned());
    }
    if rng.chance(1, 2) {
        let (object, _) = noun_phrase(rng, true, "the");
        words.extend(object);
    }
    let mut sentence = words.join(" ");
    // Capitalise the first letter (a no-op when the article is present).
    sentence = capitalize(&sentence);
    sentence.push('.');
    sentence
}

pub fn generate_sentences(rng: &mut Rng, count: u64) -> String {
    let mut parts: Vec<String> = Vec::new();
    for _ in 0..count {
        parts.push(generate_sentence(rng));
    }
    parts.join(" ")
}

pub fn generate_prompt(
    rng: &mut Rng,
    language: SupportedLanguage,
    number_of_words: u64,
    full_sentences: Option<u64>,
) -> String {
    if let Some(n) = full_sentences {
        generate_sentences(rng, n)
    } else {
        generate_words(rng, language, number_of_words)
    }
}
