use std::collections::VecDeque;
use std::io::{self, Write};

// ---------------------------------------------------------------------------
//  Minimal terminal handling built directly on libc facilities via FFI.
//  (No external crates are used anywhere in this program.)
// ---------------------------------------------------------------------------

mod ffi {
    use std::ffi::{c_int, c_ulong, c_void};

    #[repr(align(8))]
    pub struct Termios(pub [u8; 256]);

    #[repr(C)]
    pub struct PollFd {
        pub fd: c_int,
        pub events: i16,
        pub revents: i16,
    }

    #[repr(C)]
    #[derive(Default)]
    pub struct Winsize {
        pub ws_row: u16,
        pub ws_col: u16,
        pub ws_xpixel: u16,
        pub ws_ypixel: u16,
    }

    extern "C" {
        pub fn tcgetattr(fd: c_int, termios: *mut Termios) -> c_int;
        pub fn tcsetattr(fd: c_int, action: c_int, termios: *const Termios) -> c_int;
        pub fn cfmakeraw(termios: *mut Termios);
        pub fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
        pub fn poll(fds: *mut PollFd, nfds: c_ulong, timeout: c_int) -> c_int;
        pub fn read(fd: c_int, buf: *mut c_void, count: usize) -> isize;
    }
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;
const POLLIN: i16 = 0x1;

pub struct RawTerminal {
    original: ffi::Termios,
    enabled: bool,
}

impl RawTerminal {
    pub fn enable() -> io::Result<RawTerminal> {
        unsafe {
            let mut original = ffi::Termios([0u8; 256]);
            if ffi::tcgetattr(0, &mut original) != 0 {
                return Err(io::Error::last_os_error());
            }
            let mut raw = ffi::Termios(original.0);
            ffi::cfmakeraw(&mut raw);
            if ffi::tcsetattr(0, TCSANOW, &raw) != 0 {
                return Err(io::Error::last_os_error());
            }
            Ok(RawTerminal {
                original,
                enabled: true,
            })
        }
    }

    pub fn disable(&mut self) {
        if self.enabled {
            unsafe {
                ffi::tcsetattr(0, TCSANOW, &self.original);
            }
            self.enabled = false;
        }
    }
}

/// Terminal size as (columns, rows); mirrors what crossterm does:
/// try stdout, then stdin, then stderr, then fall back to 80x24.
pub fn terminal_size() -> (u16, u16) {
    for fd in [1i32, 0, 2] {
        unsafe {
            let mut ws = ffi::Winsize::default();
            if ffi::ioctl(fd, TIOCGWINSZ, &mut ws as *mut ffi::Winsize) == 0 {
                if ws.ws_col > 0 && ws.ws_row > 0 {
                    return (ws.ws_col, ws.ws_row);
                }
            }
        }
    }
    (80, 24)
}

// ---------------------------------------------------------------------------
//  Input events
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyCode {
    Char(char),
    Backspace,
    Esc,
    Left,
    Right,
    /// Any other key (arrows up/down, F-keys, Enter, Tab, ...).
    Other,
}

#[derive(Debug, Clone, Copy)]
pub struct KeyEvent {
    pub code: KeyCode,
    pub ctrl: bool,
}

pub struct InputParser {
    buffer: VecDeque<u8>,
}

enum ParseResult {
    Key(KeyEvent),
    Ignored,
    NeedMore,
}

impl InputParser {
    pub fn new() -> Self {
        InputParser {
            buffer: VecDeque::new(),
        }
    }

    /// Wait up to `timeout_ms` for input to become readable.
    /// Returns true if stdin is readable.
    pub fn poll_readable(timeout_ms: i32) -> bool {
        let mut pfd = ffi::PollFd {
            fd: 0,
            events: POLLIN,
            revents: 0,
        };
        let r = unsafe { ffi::poll(&mut pfd, 1, timeout_ms) };
        r > 0 && (pfd.revents & POLLIN) != 0
    }

    /// Read whatever is currently available from stdin into the
    /// internal buffer.  Returns false on EOF / error.
    pub fn fill(&mut self) -> bool {
        let mut buf = [0u8; 8192];
        let n = unsafe { ffi::read(0, buf.as_mut_ptr() as *mut _, buf.len()) };
        if n <= 0 {
            return false;
        }
        self.buffer.extend(&buf[..n as usize]);
        true
    }

    pub fn has_pending(&self) -> bool {
        !self.buffer.is_empty()
    }

    /// Try to take the next key event out of the buffered bytes.
    /// Returns None if more bytes are needed (or the bytes did not
    /// amount to a key event, e.g. a mouse report).
    pub fn next_key(&mut self) -> Option<KeyEvent> {
        loop {
            match self.parse_one() {
                ParseResult::Key(k) => return Some(k),
                ParseResult::Ignored => {
                    if self.buffer.is_empty() {
                        return None;
                    }
                    continue;
                }
                ParseResult::NeedMore => return None,
            }
        }
    }

    fn parse_one(&mut self) -> ParseResult {
        if self.buffer.is_empty() {
            return ParseResult::NeedMore;
        }
        let b0 = self.buffer[0];
        match b0 {
            0x1b => self.parse_escape(),
            0x7f => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Backspace,
                    ctrl: false,
                })
            }
            b'\r' | b'\n' => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Other,
                    ctrl: false,
                })
            }
            b'\t' => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Other,
                    ctrl: false,
                })
            }
            0x03 => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char('c'),
                    ctrl: true,
                })
            }
            0x00 => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char(' '),
                    ctrl: true,
                })
            }
            0x01..=0x1a => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char((b'a' + (b0 - 1)) as char),
                    ctrl: true,
                })
            }
            0x1c..=0x1f => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char((b0 + 64) as char),
                    ctrl: true,
                })
            }
            _ => {
                // A (possibly multi-byte) character, or an invalid byte.
                let available: Vec<u8> = self.buffer.iter().copied().collect();
                match std::str::from_utf8(&available) {
                    Ok(s) => {
                        let mut chars = s.chars();
                        let c = chars.next().unwrap();
                        for _ in 0..c.len_utf8() {
                            self.buffer.pop_front();
                        }
                        ParseResult::Key(KeyEvent {
                            code: KeyCode::Char(c),
                            ctrl: false,
                        })
                    }
                    Err(e) => {
                        let valid = e.valid_up_to();
                        if valid > 0 {
                            // Shouldn't happen (we consume char by
                            // char), but drop the valid prefix safely.
                            for _ in 0..valid {
                                self.buffer.pop_front();
                            }
                            ParseResult::Ignored
                        } else if e.error_len().is_none() && available.len() < 4 {
                            // Incomplete sequence; wait for the rest.
                            ParseResult::NeedMore
                        } else {
                            self.buffer.pop_front();
                            ParseResult::Ignored
                        }
                    }
                }
            }
        }
    }

    fn parse_escape(&mut self) -> ParseResult {
        // buffer[0] == ESC
        if self.buffer.len() == 1 {
            self.buffer.pop_front();
            return ParseResult::Key(KeyEvent {
                code: KeyCode::Esc,
                ctrl: false,
            });
        }
        match self.buffer[1] {
            b'[' => self.parse_csi(),
            b'O' => {
                if self.buffer.len() < 3 {
                    return ParseResult::NeedMore;
                }
                let final_byte = self.buffer[2];
                self.buffer.drain(..3);
                let code = match final_byte {
                    b'C' => KeyCode::Right,
                    b'D' => KeyCode::Left,
                    _ => KeyCode::Other,
                };
                ParseResult::Key(KeyEvent { code, ctrl: false })
            }
            0x1b => {
                // ESC ESC ... — treat the first ESC as Escape.
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Esc,
                    ctrl: false,
                })
            }
            0x7f => {
                self.buffer.drain(..2);
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Backspace,
                    ctrl: false,
                })
            }
            _ => {
                // Alt + character.
                self.buffer.pop_front(); // ESC
                match self.parse_one() {
                    ParseResult::Key(k) => ParseResult::Key(k),
                    other => other,
                }
            }
        }
    }

    fn parse_csi(&mut self) -> ParseResult {
        // ESC [ ... final byte in 0x40..=0x7e
        let mut end = None;
        for i in 2..self.buffer.len() {
            let b = self.buffer[i];
            if (0x40..=0x7e).contains(&b) {
                end = Some(i);
                break;
            }
            if i > 32 {
                break;
            }
        }
        let Some(end) = end else {
            if self.buffer.len() > 32 {
                self.buffer.clear();
                return ParseResult::Ignored;
            }
            return ParseResult::NeedMore;
        };
        let final_byte = self.buffer[end];
        let is_mouse = self.buffer.len() > 2 && self.buffer[2] == b'<';
        self.buffer.drain(..=end);
        if is_mouse {
            return ParseResult::Ignored;
        }
        // Focus in/out reports are ignored entirely.
        if final_byte == b'I' || final_byte == b'O' {
            return ParseResult::Ignored;
        }
        let code = match final_byte {
            b'C' => KeyCode::Right,
            b'D' => KeyCode::Left,
            _ => KeyCode::Other,
        };
        ParseResult::Key(KeyEvent { code, ctrl: false })
    }
}

