const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;
const POLLIN: i16 = 0x1;

pub struct RawTerminal {
    original: ffi::Termios,
    enabled: bool,
}

impl RawTerminal {
    pub fn enable() -> io::Result<RawTerminal> {
        unsafe {
            let mut original = ffi::Termios([0u8; 256]);
            if ffi::tcgetattr(0, &mut original) != 0 {
                return Err(io::Error::last_os_error());
            }
            let mut raw = ffi::Termios(original.0);
            ffi::cfmakeraw(&mut raw);
            if ffi::tcsetattr(0, TCSANOW, &raw) != 0 {
                return Err(io::Error::last_os_error());
            }
            Ok(RawTerminal {
                original,
                enabled: true,
            })
        }
    }

    pub fn disable(&mut self) {
        if self.enabled {
            unsafe {
                ffi::tcsetattr(0, TCSANOW, &self.original);
            }
            self.enabled = false;
        }
    }
}

/// Terminal size as (columns, rows); mirrors what crossterm does:
/// try stdout, then stdin, then stderr, then fall back to 80x24.
pub fn terminal_size() -> (u16, u16) {
    for fd in [1i32, 0, 2] {
        unsafe {
            let mut ws = ffi::Winsize::default();
            if ffi::ioctl(fd, TIOCGWINSZ, &mut ws as *mut ffi::Winsize) == 0 {
                if ws.ws_col > 0 && ws.ws_row > 0 {
                    return (ws.ws_col, ws.ws_row);
                }
            }
        }
    }
    (80, 24)
}

// ---------------------------------------------------------------------------
//  Input events
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyCode {
    Char(char),
    Backspace,
    Esc,
    Left,
    Right,
    /// Any other key (arrows up/down, F-keys, Enter, Tab, ...).
    Other,
}

#[derive(Debug, Clone, Copy)]
pub struct KeyEvent {
    pub code: KeyCode,
    pub ctrl: bool,
}

pub struct InputParser {
    buffer: VecDeque<u8>,
}

enum ParseResult {
    Key(KeyEvent),
    Ignored,
    NeedMore,
}

impl InputParser {
    pub fn new() -> Self {
        InputParser {
            buffer: VecDeque::new(),
        }
    }

    /// Wait up to `timeout_ms` for input to become readable.
    /// Returns true if stdin is readable.
    pub fn poll_readable(timeout_ms: i32) -> bool {
        let mut pfd = ffi::PollFd {
            fd: 0,
            events: POLLIN,
            revents: 0,
        };
        let r = unsafe { ffi::poll(&mut pfd, 1, timeout_ms) };
        r > 0 && (pfd.revents & POLLIN) != 0
    }

    /// Read whatever is currently available from stdin into the
    /// internal buffer.  Returns false on EOF / error.
    pub fn fill(&mut self) -> bool {
        let mut buf = [0u8; 8192];
        let n = unsafe { ffi::read(0, buf.as_mut_ptr() as *mut _, buf.len()) };
        if n <= 0 {
            return false;
        }
        self.buffer.extend(&buf[..n as usize]);
        true
    }

    pub fn has_pending(&self) -> bool {
        !self.buffer.is_empty()
    }

    /// Try to take the next key event out of the buffered bytes.
    /// Returns None if more bytes are needed (or the bytes did not
    /// amount to a key event, e.g. a mouse report).
    pub fn next_key(&mut self) -> Option<KeyEvent> {
        loop {
            match self.parse_one() {
                ParseResult::Key(k) => return Some(k),
                ParseResult::Ignored => {
                    if self.buffer.is_empty() {
                        return None;
                    }
                    continue;
                }
                ParseResult::NeedMore => return None,
            }
        }
    }

    fn parse_one(&mut self) -> ParseResult {
        if self.buffer.is_empty() {
            return ParseResult::NeedMore;
        }
        let b0 = self.buffer[0];
        match b0 {
            0x1b => self.parse_escape(),
            0x7f => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Backspace,
                    ctrl: false,
                })
            }
            b'\r' | b'\n' => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Other,
                    ctrl: false,
                })
            }
            b'\t' => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Other,
                    ctrl: false,
                })
            }
            0x03 => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char('c'),
                    ctrl: true,
                })
            }
            0x00 => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char(' '),
                    ctrl: true,
                })
            }
            0x01..=0x1a => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char((b'a' + (b0 - 1)) as char),
                    ctrl: true,
                })
            }
            0x1c..=0x1f => {
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Char((b0 + 64) as char),
                    ctrl: true,
                })
            }
            _ => {
                // A (possibly multi-byte) character, or an invalid byte.
                let available: Vec<u8> = self.buffer.iter().copied().collect();
                match std::str::from_utf8(&available) {
                    Ok(s) => {
                        let mut chars = s.chars();
                        let c = chars.next().unwrap();
                        for _ in 0..c.len_utf8() {
                            self.buffer.pop_front();
                        }
                        ParseResult::Key(KeyEvent {
                            code: KeyCode::Char(c),
                            ctrl: false,
                        })
                    }
                    Err(e) => {
                        let valid = e.valid_up_to();
                        if valid > 0 {
                            // Shouldn't happen (we consume char by
                            // char), but drop the valid prefix safely.
                            for _ in 0..valid {
                                self.buffer.pop_front();
                            }
                            ParseResult::Ignored
                        } else if e.error_len().is_none() && available.len() < 4 {
                            // Incomplete sequence; wait for the rest.
                            ParseResult::NeedMore
                        } else {
                            self.buffer.pop_front();
                            ParseResult::Ignored
                        }
                    }
                }
            }
        }
    }

    fn parse_escape(&mut self) -> ParseResult {
        // buffer[0] == ESC
        if self.buffer.len() == 1 {
            self.buffer.pop_front();
            return ParseResult::Key(KeyEvent {
                code: KeyCode::Esc,
                ctrl: false,
            });
        }
        match self.buffer[1] {
            b'[' => self.parse_csi(),
            b'O' => {
                if self.buffer.len() < 3 {
                    return ParseResult::NeedMore;
                }
                let final_byte = self.buffer[2];
                self.buffer.drain(..3);
                let code = match final_byte {
                    b'C' => KeyCode::Right,
                    b'D' => KeyCode::Left,
                    _ => KeyCode::Other,
                };
                ParseResult::Key(KeyEvent { code, ctrl: false })
            }
            0x1b => {
                // ESC ESC ... — treat the first ESC as Escape.
                self.buffer.pop_front();
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Esc,
                    ctrl: false,
                })
            }
            0x7f => {
                self.buffer.drain(..2);
                ParseResult::Key(KeyEvent {
                    code: KeyCode::Backspace,
                    ctrl: false,
                })
            }
            _ => {
                // Alt + character.
                self.buffer.pop_front(); // ESC
                match self.parse_one() {
                    ParseResult::Key(k) => ParseResult::Key(k),
                    other => other,
                }
            }
        }
    }

    fn parse_csi(&mut self) -> ParseResult {
        // ESC [ ... final byte in 0x40..=0x7e
        let mut end = None;
        for i in 2..self.buffer.len() {
            let b = self.buffer[i];
            if (0x40..=0x7e).contains(&b) {
                end = Some(i);
                break;
            }
            if i > 32 {
                break;
            }
        }
        let Some(end) = end else {
            if self.buffer.len() > 32 {
                self.buffer.clear();
                return ParseResult::Ignored;
            }
            return ParseResult::NeedMore;
        };
        let final_byte = self.buffer[end];
        let is_mouse = self.buffer.len() > 2 && self.buffer[2] == b'<';
        self.buffer.drain(..=end);
        if is_mouse {
            return ParseResult::Ignored;
        }
        // Focus in/out reports are ignored entirely.
        if final_byte == b'I' || final_byte == b'O' {
            return ParseResult::Ignored;
        }
        let code = match final_byte {
            b'C' => KeyCode::Right,
            b'D' => KeyCode::Left,
            _ => KeyCode::Other,
        };
        ParseResult::Key(KeyEvent { code, ctrl: false })
    }
}

// ---------------------------------------------------------------------------
//  Cell buffer and diff rendering
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Reset,
    Red,
    Green,
    Magenta,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Style {
    pub fg: Color,
    pub bold: bool,
    pub dim: bool,
    pub italic: bool,
    pub underlined: bool,
}

impl Default for Color {
    fn default() -> Self {
        Color::Reset
    }
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn fg(mut self, fg: Color) -> Style {
        self.fg = fg;
        self
    }
    pub fn bold(mut self) -> Style {
        self.bold = true;
        self
    }
    pub fn dim(mut self) -> Style {
        self.dim = true;
        self
    }
    pub fn italic(mut self) -> Style {
        self.italic = true;
        self
    }
    pub fn underlined(mut self) -> Style {
        self.underlined = true;
        self
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Cell {
    pub symbol: String,
    pub style: Style,
    pub skip: bool,
}

impl Default for Cell {
    fn default() -> Self {
        Cell {
            symbol: " ".to_owned(),
            style: Style::default(),
            skip: false,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Buffer {
    pub width: u16,
    pub height: u16,
    pub cells: Vec<Cell>,
}

impl Buffer {
    pub fn new(width: u16, height: u16) -> Buffer {
        Buffer {
            width,
            height,
            cells: vec![Cell::default(); width as usize * height as usize],
        }
    }

    fn index(&self, x: u16, y: u16) -> usize {
        y as usize * self.width as usize + x as usize
    }

    pub fn set_cell(&mut self, x: u16, y: u16, symbol: &str, style: Style) {
        if x >= self.width || y >= self.height {
            return;
        }
        let idx = self.index(x, y);
        self.cells[idx] = Cell {
            symbol: symbol.to_owned(),
            style,
            skip: false,
        };
        // Clear a following cell covered by a wide symbol.
        if unicode_width_str(symbol) == 2 && x + 1 < self.width {
            let idx2 = self.index(x + 1, y);
            self.cells[idx2] = Cell {
                symbol: String::new(),
                style,
                skip: true,
            };
        }
    }

    /// Write a string starting at (x, y), stopping before `max_x`.
    /// Returns the x position after the last written symbol.
    pub fn set_stringn(&mut self, mut x: u16, y: u16, s: &str, style: Style, max_x: u16) -> u16 {
        if y >= self.height {
            return x;
        }
        for grapheme in graphemes(s) {
            let w = unicode_width_str(grapheme);
            if w == 0 {
                continue;
            }
            if x >= max_x || x >= self.width {
                break;
            }
            if x as usize + w > max_x as usize {
                break;
            }
            self.set_cell(x, y, grapheme, style);
            x += w as u16;
        }
        x
    }

    pub fn set_string(&mut self, x: u16, y: u16, s: &str, style: Style) -> u16 {
        let w = self.width;
        self.set_stringn(x, y, s, style, w)
    }
}

/// Split into the units we place in cells.  This is deliberately
/// simple (one Unicode scalar at a time, with combining marks glued
/// to the preceding base character), which is enough for the text
/// this program draws.
pub fn graphemes(s: &str) -> Vec<&str> {
    let mut out: Vec<&str> = Vec::new();
    let mut start = 0usize;
    let mut prev_end = 0usize;
    let mut first = true;
    for (idx, ch) in s.char_indices() {
        if first {
            first = false;
            prev_end = idx + ch.len_utf8();
            continue;
        }
        if is_combining(ch) {
            prev_end = idx + ch.len_utf8();
            continue;
        }
        out.push(&s[start..prev_end]);
        start = idx;
        prev_end = idx + ch.len_utf8();
    }
    if prev_end > start {
        out.push(&s[start..prev_end]);
    }
    out
}

fn is_combining(c: char) -> bool {
    matches!(c as u32, 0x0300..=0x036F | 0x1AB0..=0x1AFF | 0x1DC0..=0x1DFF | 0x20D0..=0x20FF | 0xFE20..=0xFE2F)
}

/// Display width of one character, following the usual
/// unicode-width conventions closely enough for this program.
pub fn unicode_width_char(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 0x20 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    if is_combining(c) {
        return 0;
    }
    if is_wide(cp) {
        2
    } else {
        1
    }
}

fn is_wide(cp: u32) -> bool {
    matches!(cp,
        0x1100..=0x115F
        | 0x231A..=0x231B
        | 0x2329..=0x232A
        | 0x23E9..=0x23EC
        | 0x23F0
        | 0x23F3
        | 0x25FD..=0x25FE
        | 0x2614..=0x2615
        | 0x2648..=0x2653
        | 0x267F
        | 0x2693
        | 0x26A1
        | 0x26AA..=0x26AB
        | 0x26BD..=0x26BE
        | 0x26C4..=0x26C5
        | 0x26CE
        | 0x26D1
        | 0x26EA
        | 0x26F2..=0x26F3
        | 0x26F5
        | 0x26FA
        | 0x26FD
        | 0x2705
        | 0x270A..=0x270B
        | 0x2728
        | 0x274C
        | 0x274E
        | 0x2753..=0x2755
        | 0x2757
        | 0x2795..=0x2797
        | 0x27B0
        | 0x27BF
        | 0x2B1B..=0x2B1C
        | 0x2B50
        | 0x2B55
        | 0x2E80..=0x303E
        | 0x3040..=0xA4CF
        | 0xAC00..=0xD7A3
        | 0xF900..=0xFAFF
        | 0xFE10..=0xFE19
        | 0xFE30..=0xFE6F
        | 0xFF00..=0xFF60
        | 0xFFE0..=0xFFE6
        | 0x1F300..=0x1F64F
        | 0x1F900..=0x1F9FF
        | 0x20000..=0x3FFFD)
}

pub fn unicode_width_str(s: &str) -> usize {
    s.chars().map(unicode_width_char).sum()
}

pub struct Renderer {
    previous: Buffer,
}

impl Renderer {
    pub fn new() -> Renderer {
        Renderer {
            previous: Buffer::new(0, 0),
        }
    }

    pub fn draw<W: Write>(&mut self, out: &mut W, buffer: &Buffer) -> io::Result<()> {
        let mut output = String::new();
        if self.previous.width != buffer.width || self.previous.height != buffer.height {
            if self.previous.width != 0 {
                output.push_str("\x1b[2J");
            }
            self.previous = Buffer::new(buffer.width, buffer.height);
        }

        let mut current_style = Style::default();
        let mut cursor: Option<(u16, u16)> = None;

        for y in 0..buffer.height {
            for x in 0..buffer.width {
                let idx = buffer.index(x, y);
                let cell = &buffer.cells[idx];
                if cell.skip {
                    continue;
                }
                if *cell == self.previous.cells[idx] {
                    continue;
                }
                if cursor != Some((x, y)) {
                    output.push_str(&format!("\x1b[{};{}H", y + 1, x + 1));
                }
                if cell.style != current_style {
                    apply_style(&mut output, &mut current_style, cell.style);
                }
                output.push_str(&cell.symbol);
                let w = unicode_width_str(&cell.symbol) as u16;
                let nx = x + w;
                cursor = if nx < buffer.width {
                    Some((nx, y))
                } else {
                    None
                };
            }
        }
        output.push_str("\x1b[39m\x1b[49m\x1b[0m\x1b[?25l");
        out.write_all(output.as_bytes())?;
        out.flush()?;
        self.previous = buffer.clone();
        Ok(())
    }
}

fn apply_style(output: &mut String, current: &mut Style, target: Style) {
    // If anything needs to be switched off, reset and start again.
    let needs_reset = (current.bold && !target.bold)
        || (current.dim && !target.dim)
        || (current.italic && !target.italic)
        || (current.underlined && !target.underlined);
    if needs_reset {
        output.push_str("\x1b[0m");
        *current = Style::default();
    }
    if target.fg != current.fg {
        match target.fg {
            Color::Reset => output.push_str("\x1b[39m"),
            Color::Red => output.push_str("\x1b[38;5;1m"),
            Color::Green => output.push_str("\x1b[38;5;2m"),
            Color::Magenta => output.push_str("\x1b[38;5;5m"),
        }
        current.fg = target.fg;
    }
    if target.bold && !current.bold {
        output.push_str("\x1b[1m");
        current.bold = true;
    }
    if target.dim && !current.dim {
        output.push_str("\x1b[2m");
        current.dim = true;
    }
    if target.italic && !current.italic {
        output.push_str("\x1b[3m");
        current.italic = true;
    }
    if target.underlined && !current.underlined {
        output.push_str("\x1b[4m");
        current.underlined = true;
    }
}
RS"}

