use std::fs::OpenOptions;
use std::io::Write;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

mod ffi {
    use std::ffi::{c_char, c_int, c_long};

    #[repr(C)]
    #[derive(Default)]
    pub struct Tm {
        pub tm_sec: c_int,
        pub tm_min: c_int,
        pub tm_hour: c_int,
        pub tm_mday: c_int,
        pub tm_mon: c_int,
        pub tm_year: c_int,
        pub tm_wday: c_int,
        pub tm_yday: c_int,
        pub tm_isdst: c_int,
        pub tm_gmtoff: c_long,
        pub tm_zone: *const c_char,
    }

    extern "C" {
        pub fn localtime_r(timep: *const i64, result: *mut Tm) -> *mut Tm;
    }
}

const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

/// Format the current local time the way ctime does,
/// e.g. "Fri Oct  9 03:04:56 2026".
fn formatted_now() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    unsafe {
        let mut tm = ffi::Tm::default();
        if !ffi::localtime_r(&secs, &mut tm).is_null() {
            let weekday = WEEKDAYS
                .get(tm.tm_wday as usize)
                .copied()
                .unwrap_or("Sun");
            let month = MONTHS.get(tm.tm_mon as usize).copied().unwrap_or("Jan");
            return format!(
                "{} {} {:2} {:02}:{:02}:{:02} {}",
                weekday,
                month,
                tm.tm_mday,
                tm.tm_hour,
                tm.tm_min,
                tm.tm_sec,
                tm.tm_year + 1900
            );
        }
    }
    // Fallback: UTC via a civil-date conversion.
    format_utc(secs)
}

fn format_utc(secs: i64) -> String {
    let days = secs.div_euclid(86400);
    let tod = secs.rem_euclid(86400);
    let (hour, minute, second) = (tod / 3600, (tod % 3600) / 60, tod % 60);
    // 1970-01-01 was a Thursday.
    let weekday = WEEKDAYS[((days % 7 + 7 + 4) % 7) as usize];
    // Howard Hinnant's civil_from_days.
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let mp = (5 * (doe - (365 * yoe + yoe / 4 - yoe / 100)) + 2) / 153;
    let day = doe - (365 * yoe + yoe / 4 - yoe / 100) - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if month <= 2 { y + 1 } else { y };
    format!(
        "{} {} {:2} {:02}:{:02}:{:02} {}",
        weekday,
        MONTHS[(month - 1) as usize],
        day,
        hour,
        minute,
        second,
        year
    )
}

fn config_dir() -> Option<PathBuf> {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            let p = PathBuf::from(&xdg);
            if p.is_absolute() {
                return Some(p);
            }
        }
    }
    #[allow(deprecated)]
    let home = std::env::home_dir()?;
    Some(home.join(".config"))
}

pub struct LogRecord {
    pub num_words: u64,
    pub num_secs: Option<u64>,
    pub elapsed_secs: f64,
    pub wpm: String,
    pub accuracy: String,
    pub std_dev: f64,
}

/// Append one result row to `<config>/thokr/log.csv`.
///
/// A header is written first only when the file did not previously
/// exist.  Every failure along the way is silently ignored, exactly
/// like the reference.
pub fn append_log(record: &LogRecord) {
    let Some(mut dir) = config_dir() else {
        return;
    };
    dir.push("thokr");
    if std::fs::create_dir_all(&dir).is_err() {
        // The directory may already exist as something unusable; the
        // open below will fail too and that is fine.
    }
    let path = dir.join("log.csv");
    let existed = path.exists();
    let Ok(mut file) = OpenOptions::new().create(true).append(true).open(&path) else {
        return;
    };
    let mut out = String::new();
    if !existed {
        out.push_str("date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev\n");
    }
    let num_secs = match record.num_secs {
        Some(s) => format!("{:.2}", s as f64),
        None => String::new(),
    };
    out.push_str(&format!(
        "{},{},{},{:.2},{},{},{:.2}\n",
        formatted_now(),
        record.num_words,
        num_secs,
        record.elapsed_secs,
        record.wpm,
        record.accuracy,
        record.std_dev
    ));
    let _ = file.write_all(out.as_bytes());
    let _ = file.flush();
}
