        self.test = Test::new(prompt, self.config.number_of_secs);
    }

    pub fn display_results(&self) -> Results {
        self.test.results.clone().unwrap_or_default()
    }

    pub fn handle_key(&mut self, key: KeyEvent) -> Action {
        self.handle_key_at(key, Instant::now())
    }

    pub fn handle_key_at(&mut self, key: KeyEvent, now: Instant) -> Action {
        if key.code == KeyCode::Esc {
            return Action::Quit;
        }
        if key.code == KeyCode::Char('c') && key.ctrl {
            return Action::Quit;
        }
        match key.code {
            KeyCode::Left => {
                self.reset_same();
                return Action::Continue;
            }
            KeyCode::Right => {
                self.reset_new();
                return Action::Continue;
            }
            _ => {}
        }

        if self.test.is_complete() {
            match key.code {
                KeyCode::Char('r') => self.reset_same(),
                KeyCode::Char('n') => self.reset_new(),
                _ => {}
            }
            return Action::Continue;
        }

        match key.code {
            KeyCode::Backspace => {
                self.test.input.pop();
                self.test.times.pop();
            }
            KeyCode::Char(c) => {
                if !self.test.started {
                    self.test.started = true;
                    self.test.start = Some(now);
                }
                let start = self.test.start.unwrap_or(now);
                let elapsed = now.duration_since(start);
                self.test.input.push(c);
                self.test.times.push(elapsed);
                if self.test.is_complete() {
                    self.finish(now, FinishCause::Typed);
                }
            }
            _ => {}
        }
        Action::Continue
    }

    /// Advance the countdown, if any.  Returns whether the screen
    /// needs to be redrawn.
    pub fn on_tick(&mut self, now: Instant) -> bool {
        if !self.test.started || self.test.secs_remaining.is_none() || self.test.is_complete() {
            return false;
        }
        if let Some(remaining) = self.test.secs_remaining {
            let remaining = remaining - 0.1;
            self.test.secs_remaining = Some(remaining);
            if remaining <= 0.0 {
                self.finish(now, FinishCause::Timer);
            }
        }
        true
    }

    fn finish(&mut self, now: Instant, cause: FinishCause) {
        let results = compute_results(&self.test, now, matches!(cause, FinishCause::Typed));
        let num_words = if self.config.full_sentences.is_some() {
            0
        } else {
            self.config.number_of_words
        };
        append_log(&LogRecord {
            num_words,
            num_secs: self.config.number_of_secs,
            elapsed_secs: results.elapsed_secs,
            wpm: results.wpm.clone(),
            accuracy: results.accuracy.clone(),
            std_dev: results.std_dev,
        });
        self.test.results = Some(results);
    }
}

fn compute_results(test: &Test, now: Instant, typed: bool) -> Results {
    let start = test.start.unwrap_or(now);
    let finish_elapsed = now.duration_since(start);

    // Group the surviving correct characters by the (1-based)
    // second in which they were typed.
    let mut buckets: BTreeMap<u64, usize> = BTreeMap::new();
    let mut correct: usize = 0;
    for (i, &ch) in test.input.iter().enumerate() {
        if let Some(&expected) = test.prompt_chars.get(i) {
            if ch == expected {
                correct += 1;
                let bucket = test
                    .times
                    .get(i)
                    .map(|t| t.as_secs() + 1)
                    .unwrap_or(1);
                *buckets.entry(bucket).or_insert(0) += 1;
            }
        }
    }

    let mut points: Vec<(f64, f64)> = Vec::new();
    let mut cumulative: usize = 0;
    for (&bucket, &count) in buckets.iter() {
        cumulative += count;
        let x = bucket as f64;
        let y = (cumulative as f64 / 5.0) / (x / 60.0);
        points.push((x, y));
    }

    // Standard deviation of the per-second correct-character
    // counts, ignoring the final (incomplete) second.
    let counts: Vec<f64> = buckets.values().map(|&c| c as f64).collect();
    let std_dev = population_std_dev(if counts.is_empty() {
        &[]
    } else {
        &counts[..counts.len() - 1]
    });

    let accuracy_raw = if test.input.is_empty() {
        0.0
    } else {
        (correct as f64 / test.input.len() as f64) * 100.0
    };
    let accuracy = format!("{:.0}", accuracy_raw.round());

    let raw_wpm = if correct == 0 {
        0.0
    } else if typed && finish_elapsed.as_millis() == 0 {
        // Completing the test in (recorded) zero milliseconds is
        // reported as an infinite speed.
        f64::INFINITY
    } else {
        points.last().map(|&(_, y)| y).unwrap_or(0.0)
    };

    let (wpm, x_max, y_max) = if raw_wpm.is_infinite() {
        ("inf".to_owned(), 1.0, f64::INFINITY)
    } else {
        let x_max = points.last().map(|&(x, _)| x).unwrap_or(1.0);
        let y_max = points
            .iter()
            .map(|&(_, y)| y)
            .fold(raw_wpm, f64::max);
        (format!("{:.0}", raw_wpm.ceil()), x_max, y_max)
    };

    Results {
        points: if raw_wpm.is_infinite() {
            Vec::new()
        } else {
            points
        },
        x_max,
        y_max,
        wpm,
        accuracy,
        std_dev,
        elapsed_secs: finish_elapsed.as_secs_f64(),
    }
}

fn population_std_dev(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let mean: f64 = values.iter().sum::<f64>() / values.len() as f64;
    let variance: f64 =
        values.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / values.len() as f64;
    variance.sqrt()
}
