{"command":"cat <<'RS' > src/ui.rs
use crate::app::{App, Results, Test};
use crate::terminal::{unicode_width_char, unicode_width_str, Buffer, Color, Style};

#[derive(Debug, Clone, Copy)]
struct Rect {
    x: u16,
    y: u16,
    width: u16,
    height: u16,
}

impl Rect {
    fn right(self) -> u16 {
        self.x.saturating_add(self.width)
    }
    fn bottom(self) -> u16 {
        self.y.saturating_add(self.height)
    }
}

#[derive(Debug, Clone)]
struct Symbol {
    text: String,
    ch: char,
    style: Style,
}

impl Symbol {
    fn width(&self) -> usize {
        unicode_width_char(self.ch)
    }
}

fn typed_style(correct: bool) -> Style {
    if correct {
        Style::new().fg(Color::Green).bold()
    } else {
        Style::new().fg(Color::Red).bold()
    }
}

fn current_style() -> Style {
    Style::new().bold().dim().underlined()
}

fn pending_style() -> Style {
    Style::new().bold().dim()
}

/// Build the styled symbols that make up the prompt line: the part
/// already typed (green when right, red when wrong — with a
/// mistyped space shown as a middle dot so the mistake is visible),
/// then the character under the cursor, then the rest.
fn prompt_symbols(test: &Test) -> Vec<Symbol> {
    let mut symbols: Vec<Symbol> = Vec::new();
    for (i, &ch) in test.input.iter().enumerate() {
        if let Some(&expected) = test.prompt_chars.get(i) {
            let correct = ch == expected;
            let shown = if !correct && expected == ' ' {
                '·'
            } else {
                expected
            };
            symbols.push(Symbol {
                text: shown.to_string(),
                ch: shown,
                style: typed_style(correct),
            });
        }
    }
    if test.input.len() < test.prompt_chars.len() {
        let index = test.input.len();
        // The reference splits the prompt here by byte index; keep
        // that exact operation (including where it panics for a
        // prompt whose current character is not ASCII).
        let current = &test.prompt[index..index + 1];
        for ch in current.chars() {
            symbols.push(Symbol {
                text: ch.to_string(),
                ch,
                style: current_style(),
            });
        }
        let rest = &test.prompt[index + 1..];
        for ch in rest.chars() {
            symbols.push(Symbol {
                text: ch.to_string(),
                ch,
                style: pending_style(),
            });
        }
    }
    symbols
}

fn add_split_word(
    word: &[Symbol],
    width: usize,
    lines: &mut Vec<Vec<Symbol>>,
    line: &mut Vec<Symbol>,
    line_width: &mut usize,
) {
    let mut rest = word;
    loop {
        let rest_width: usize = rest.iter().map(|s| s.width()).sum();
        if rest_width == 0 {
            line.extend(rest.iter().cloned());
            return;
        }
        let remaining = width.saturating_sub(*line_width);
        if rest_width <= remaining {
            line.extend(rest.iter().cloned());
            *line_width += rest_width;
            return;
        }
        if rest_width <= width {
            // The word fits on a line of its own.
            if !line.is_empty() {
                lines.push(std::mem::take(line));
                *line_width = 0;
            }
            line.extend(rest.iter().cloned());
            *line_width += rest_width;
            return;
        }
        // The word is longer than a whole line: fill this line with
        // as much of it as fits, then continue on the next.
        let mut taken = 0usize;
        let mut taken_width = 0usize;
        for sym in rest.iter() {
            let w = sym.width();
            if taken_width + w > remaining && taken > 0 {
                break;
            }
            if w > 0 && taken_width + w > remaining && taken == 0 {
                break;
            }
            taken += 1;
            taken_width += w;
        }
        if taken == 0 {
            if !line.is_empty() {
                lines.push(std::mem::take(line));
                *line_width = 0;
                continue;
            }
            // A single symbol wider than the line; place it anyway.
            taken = 1;
            taken_width = rest[0].width();
        }
        line.extend(rest[..taken].iter().cloned());
        *line_width += taken_width;
        rest = &rest[taken..];
        if !rest.is_empty() {
            lines.push(std::mem::take(line));
            *line_width = 0;
        }
    }
}

fn wrap_symbols(symbols: &[Symbol], width: u16) -> Vec<Vec<Symbol>> {
    let width = width as usize;
    if width == 0 {
        return Vec::new();
    }
    let mut lines: Vec<Vec<Symbol>> = Vec::new();
    let mut line: Vec<Symbol> = Vec::new();
    let mut line_width: usize = 0;
    let mut i: usize = 0;
    let mut first_line = true;

    while i < symbols.len() {
        let space_start = i;
        while i < symbols.len() && symbols[i].ch == ' ' {
            i += 1;
        }
        let spaces = &symbols[space_start..i];
        if i >= symbols.len() {
            // Trailing spaces.
            for sp in spaces {
                if line_width >= width && !line.is_empty() {
                    lines.push(std::mem::take(&mut line));
                    line_width = 0;
                    first_line = false;
                }
                line.push(sp.clone());
                line_width += 1;
            }
            break;
        }
        let word_start = i;
        while i < symbols.len() && symbols[i].ch != ' ' {
            i += 1;
        }
        let word = &symbols[word_start..i];
        let word_width: usize = word.iter().map(|s| s.width()).sum();

        if line.is_empty() {
            if first_line && !spaces.is_empty() {
                // At most one leading space survives at the very
                // start of the prompt.
                line.push(spaces[0].clone());
                line_width = 1;
            }
            add_split_word(word, width, &mut lines, &mut line, &mut line_width);
            if !lines.is_empty() {
                first_line = false;
            }
        } else if line_width + spaces.len() + word_width <= width {
            line.extend(spaces.iter().cloned());
            line.extend(word.iter().cloned());
            line_width += spaces.len() + word_width;
        } else {
            lines.push(std::mem::take(&mut line));
            line_width = 0;
            first_line = false;
            add_split_word(word, width, &mut lines, &mut line, &mut line_width);
        }
    }
    if !line.is_empty() || lines.is_empty() {
        lines.push(line);
    }
    lines
}

fn draw_symbols(buffer: &mut Buffer, rect: Rect, lines: &[Vec<Symbol>]) {
    for (row, line) in lines.iter().enumerate() {
        if row as u16 >= rect.height {
            break;
        }
        let y = rect.y + row as u16;
        let mut x = rect.x;
        let mut run_style: Option<Style> = None;
        let mut run = String::new();
        let mut run_start = x;
        for sym in line {
            if run_style != Some(sym.style) {
                if let Some(style) = run_style {
                    if !run.is_empty() {
                        buffer.set_stringn(run_start, y, &run, style, rect.right());
                    }
                }
                run_style = Some(sym.style);
                run_start = x;
                run = String::new();
            }
            run.push_str(&sym.text);
            x += sym.width() as u16;
        }
        if let Some(style) = run_style {
            if !run.is_empty() {
                buffer.set_stringn(run_start, y, &run, style, rect.right());
            }
        }
    }
}

fn draw_test(buffer: &mut Buffer, test: &Test) {
    let frame_w = buffer.width;
    let frame_h = buffer.height;
    let max_width = frame_w.saturating_sub(10);
    let prompt_width = unicode_width_str(&test.prompt);
    let area_width = (prompt_width.min(max_width as usize)) as u16;

    let estimated_lines: usize = if max_width == 0 || prompt_width == 0 {
        0
    } else {
        (prompt_width + max_width as usize - 1) / max_width as usize
    };
    let estimated_height: usize = if estimated_lines <= 1 {
        1
    } else {
        estimated_lines + 1
    };
    let area_x = frame_w / 2 - area_width / 2;
    let area_y: u16 = if estimated_height >= frame_h as usize {
        0
    } else {
        (frame_h - estimated_height as u16) / 2
    };
    let area_height: u16 = {
        let h = u16::try_from(estimated_height).unwrap_or(u16::MAX);
        h.min(frame_h.saturating_sub(area_y))
    };

    let mut prompt_y = area_y;
    if let Some(remaining) = test.secs_remaining {
        let timer = format!("{:.1}", remaining);
        let timer_width = unicode_width_str(&timer) as u16;
        let timer_x = (frame_w / 2).saturating_sub(timer_width / 2);
        buffer.set_string(timer_x, area_y, &timer, Style::new().bold().dim());
        prompt_y = area_y.saturating_add(2);
    }

    if area_width == 0 {
        return;
    }
    let symbols = prompt_symbols(test);
    let lines = wrap_symbols(&symbols, area_width);
    let rect = Rect {
        x: area_x,
        y: prompt_y,
        width: area_width,
        height: {
            let below = frame_h.saturating_sub(prompt_y);
            area_height.min(below)
        },
    };
    draw_symbols(buffer, rect, &lines);
}

// ---------------------------------------------------------------------------
//  Results screen
// ---------------------------------------------------------------------------

fn bresenham(x0: i32, y0: i32, x1: i32, y1: i32, plot: &mut impl FnMut(i32, i32)) {
    let dx = (x1 - x0).abs();
    let sx = if x0 < x1 { 1 } else { -1 };
    let dy = -(y1 - y0).abs();
    let sy = if y0 < y1 { 1 } else { -1 };
    let mut err = dx + dy;
    let (mut x, mut y) = (x0, y0);
    loop {
        plot(x, y);
        if x == x1 && y == y1 {
            break;
        }
        let e2 = 2 * err;
        if e2 >= dy {
            err += dy;
            x += sx;
        }
        if e2 <= dx {
            err += dx;
            y += sy;
        }
    }
}

fn draw_chart(buffer: &mut Buffer, area: Rect, results: &Results) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let y_top_label = format!("{:.0}", results.y_max);
    let y_bottom_label = "0";
    let label_width = unicode_width_str(&y_top_label)
        .max(unicode_width_str(y_bottom_label)) as u16;
    if label_width >= area.width {
        return;
    }
    let axis_x = area.x + label_width;
    let graph = Rect {
        x: axis_x + 1,
        y: area.y,
        width: area.width - label_width - 1,
        height: area.height.saturating_sub(2),
    };
    if graph.width == 0 || graph.height == 0 {
        return;
    }

    // --- dataset, as a braille line plot -------------------------------
    let grid_w = graph.width as i32 * 2;
    let grid_h = graph.height as i32 * 4;
    let mut dots = vec![false; (grid_w.max(0) * grid_h.max(0)) as usize];
    let plot_dot = |dots: &mut Vec<bool>, gx: i32, gy: i32| {
        if gx >= 0 && gx < grid_w && gy >= 0 && gy < grid_h {
            dots[(gy * grid_w + gx) as usize] = true;
        }
    };
    let map_point = |x: f64, y: f64| -> Option<(i32, i32)> {
        if !x.is_finite() || !y.is_finite() || !results.y_max.is_finite() {
            return None;
        }
        if x < 1.0 || x > results.x_max || y < 0.0 || y > results.y_max {
            return None;
        }
        let gx = if results.x_max <= 1.0 || grid_w <= 1 {
            0
        } else {
            ((x - 1.0) / (results.x_max - 1.0) * (grid_w - 1) as f64).round() as i32
        };
        let gy_from_bottom = if results.y_max <= 0.0 || grid_h <= 1 {
            0
        } else {
            (y / results.y_max * (grid_h - 1) as f64).round() as i32
        };
        Some((gx, grid_h - 1 - gy_from_bottom))
    };

    let mapped: Vec<(i32, i32)> = results
        .points
        .iter()
        .filter_map(|&(x, y)| map_point(x, y))
        .collect();
    if mapped.len() == 1 {
        plot_dot(&mut dots, mapped[0].0, mapped[0].1);
    }
    for pair in mapped.windows(2) {
        let (x0, y0) = pair[0];
        let (x1, y1) = pair[1];
        let mut dots_ref = &mut dots;
        bresenham(x0, y0, x1, y1, &mut |gx, gy| {
            if gx >= 0 && gx < grid_w && gy >= 0 && gy < grid_h {
                dots_ref[(gy * grid_w + gx) as usize] = true;
            }
        });
    }

    // Braille dot bit for (dx, dy) within a cell.
    let braille_bit = |dx: i32, dy: i32| -> u32 {
        match (dx, dy) {
            (0, 0) => 0x01,
            (0, 1) => 0x02,
            (0, 2) => 0x04,
            (0, 3) => 0x40,
            (1, 0) => 0x08,
            (1, 1) => 0x10,
            (1, 2) => 0x20,
            (1, 3) => 0x80,
            _ => 0,
        }
    };
    for cy in 0..graph.height {
        for cx in 0..graph.width {
            let mut bits: u32 = 0;
            for dy in 0..4i32 {
                for dx in 0..2i32 {
                    let gx = cx as i32 * 2 + dx;
                    let gy = cy as i32 * 4 + dy;
                    if dots[(gy * grid_w + gx) as usize] {
                        bits |= braille_bit(dx, dy);
                    }
                }
            }
            if bits != 0 {
                if let Some(symbol) = char::from_u32(0x2800 + bits) {
                    // Cells on the first row of the graph keep the
                    // default colour in the reference; the rest of
                    // the line is magenta.
                    let style = if cy == 0 {
                        Style::new()
                    } else {
                        Style::new().fg(Color::Magenta)
                    };
                    buffer.set_cell(
                        graph.x + cx,
                        graph.y + cy,
                        &symbol.to_string(),
                        style,
                    );
                }
            }
        }
    }

    // --- axes -------------------------------------------------------------
    for row in 0..graph.height {
        buffer.set_cell(axis_x, graph.y + row, "│", Style::new());
    }
    let x_axis_y = graph.y + graph.height;
    if x_axis_y < area.bottom() {
        buffer.set_cell(axis_x, x_axis_y, "└", Style::new());
        for x in graph.x..graph.right() {
            buffer.set_cell(x, x_axis_y, "─", Style::new());
        }
    }

    // --- labels and titles (drawn over the dataset) ----------------------
    let bold = Style::new().bold();
    let bottom_label_y = graph.y + graph.height - 1;
    buffer.set_stringn(
        area.x,
        bottom_label_y,
        y_bottom_label,
        bold,
        area.x + label_width,
    );
    buffer.set_stringn(area.x, area.y, &y_top_label, bold, area.x + label_width);

    let x_labels_y = x_axis_y + 1;
    if x_labels_y < area.bottom() {
        buffer.set_string(axis_x, x_labels_y, "1", bold);
        let last = format!("{:.2}", results.x_max);
        let last_w = unicode_width_str(&last) as u16;
        if area.right() >= last_w {
            buffer.set_string(area.right() - last_w, x_labels_y, &last, bold);
        }
    }

    // Axis titles.
    buffer.set_stringn(graph.x, graph.y, "wpm", Style::new(), graph.right());
    let seconds = "seconds";
    let sec_w = unicode_width_str(seconds) as u16;
    if graph.right() >= sec_w {
        buffer.set_string(
            graph.right() - sec_w,
            bottom_label_y,
            seconds,
            Style::new(),
        );
    }
}

fn draw_results(buffer: &mut Buffer, results: &Results) {
    let frame_w = buffer.width;
    let frame_h = buffer.height;
    let content = Rect {
        x: 5.min(frame_w),
        y: 2.min(frame_h),
        width: frame_w.saturating_sub(10),
        height: frame_h.saturating_sub(4),
    };
    if content.width == 0 || content.height == 0 {
        return;
    }
    let chart_height = content.height.saturating_sub(3);
    let chart = Rect {
        height: chart_height,
        ..content
    };
    draw_chart(buffer, chart, results);

    let summary_y = content.y + chart_height;
    if summary_y < frame_h {
        let summary = format!(
            "{} wpm   {}% acc   {:.2} sd",
            results.wpm, results.accuracy, results.std_dev
        );
        let text_w = unicode_width_str(&summary) as u16;
        let x = if text_w > content.width {
            content.x
        } else {
            (frame_w / 2).saturating_sub(text_w / 2)
        };
        buffer.set_stringn(
            x,
            summary_y,
            &summary,
            Style::new().bold(),
            content.right(),
        );
    }

    let retry_y = summary_y.saturating_add(2);
    if retry_y < frame_h {
        buffer.set_stringn(
            content.x,
            retry_y,
            "(r)etry / (n)ew / (esc)ape",
            Style::new().italic(),
            content.right(),
        );
    }
}

pub fn draw(buffer: &mut Buffer, app: &App) {
    if app.test.is_complete() {
        let results = app.display_results();
        draw_results(buffer, &results);
    } else {
        draw_test(buffer, &app.test);
    }
}
