use crate::app::{App, Results, Test};
use crate::terminal::{unicode_width_char, unicode_width_str, Buffer, Color, Style};

#[derive(Debug, Clone, Copy)]
struct Rect {
    x: u16,
    y: u16,
    width: u16,
    height: u16,
}

impl Rect {
    fn right(self) -> u16 {
        self.x.saturating_add(self.width)
    }
    fn bottom(self) -> u16 {
        self.y.saturating_add(self.height)
    }
}

#[derive(Debug, Clone)]
struct Symbol {
    text: String,
    ch: char,
    style: Style,
}

impl Symbol {
    fn width(&self) -> usize {
        unicode_width_char(self.ch)
    }
}

fn typed_style(correct: bool) -> Style {
    if correct {
        Style::new().fg(Color::Green).bold()
    } else {
        Style::new().fg(Color::Red).bold()
    }
}

fn current_style() -> Style {
    Style::new().bold().dim().underlined()
}

fn pending_style() -> Style {
    Style::new().bold().dim()
}

/// Build the styled symbols that make up the prompt line: the part
/// already typed (green when right, red when wrong — with a
/// mistyped space shown as a middle dot so the mistake is visible),
/// then the character under the cursor, then the rest.
fn prompt_symbols(test: &Test) -> Vec<Symbol> {
    let mut symbols: Vec<Symbol> = Vec::new();
    for (i, &ch) in test.input.iter().enumerate() {
        if let Some(&expected) = test.prompt_chars.get(i) {
            let correct = ch == expected;
            let shown = if !correct && expected == ' ' {
                '·'
            } else {
                expected
            };
            symbols.push(Symbol {
                text: shown.to_string(),
                ch: shown,
                style: typed_style(correct),
            });
        }
    }
    if test.input.len() < test.prompt_chars.len() {
        let index = test.input.len();
        // The reference splits the prompt here by byte index; keep
        // that exact operation (including where it panics for a
        // prompt whose current character is not ASCII).
        let current = &test.prompt[index..index + 1];
        for ch in current.chars() {
            symbols.push(Symbol {
                text: ch.to_string(),
                ch,
                style: current_style(),
            });
        }
        let rest = &test.prompt[index + 1..];
        for ch in rest.chars() {
            symbols.push(Symbol {
                text: ch.to_string(),
                ch,
                style: pending_style(),
            });
        }
    }
    symbols
}

fn add_split_word(
    word: &[Symbol],
    width: usize,
    lines: &mut Vec<Vec<Symbol>>,
    line: &mut Vec<Symbol>,
    line_width: &mut usize,
) {
    let mut rest = word;
    loop {
        let rest_width: usize = rest.iter().map(|s| s.width()).sum();
        if rest_width == 0 {
            line.extend(rest.iter().cloned());
            return;
        }
        let remaining = width.saturating_sub(*line_width);
        if rest_width <= remaining {
            line.extend(rest.iter().cloned());
            *line_width += rest_width;
            return;
        }
        if rest_width <= width {
            // The word fits on a line of its own.
            if !line.is_empty() {
                lines.push(std::mem::take(line));
                *line_width = 0;
            }
            line.extend(rest.iter().cloned());
            *line_width += rest_width;
            return;
        }
        // The word is longer than a whole line: fill this line with
        // as much of it as fits, then continue on the next.
        let mut taken = 0usize;
        let mut taken_width = 0usize;
        for sym in rest.iter() {
            let w = sym.width();
            if taken_width + w > remaining && taken > 0 {
                break;
            }
            if w > 0 && taken_width + w > remaining && taken == 0 {
                break;
            }
            taken += 1;
            taken_width += w;
        }
        if taken == 0 {
            if !line.is_empty() {
                lines.push(std::mem::take(line));
                *line_width = 0;
                continue;
            }
            // A single symbol wider than the line; place it anyway.
            taken = 1;
            taken_width = rest[0].width();
        }
        line.extend(rest[..taken].iter().cloned());
        *line_width += taken_width;
        rest = &rest[taken..];
        if !rest.is_empty() {
            lines.push(std::mem::take(line));
            *line_width = 0;
        }
    }
}

fn wrap_symbols(symbols: &[Symbol], width: u16) -> Vec<Vec<Symbol>> {
    let width = width as usize;
    if width == 0 {
        return Vec::new();
    }
    let mut lines: Vec<Vec<Symbol>> = Vec::new();
    let mut line: Vec<Symbol> = Vec::new();
    let mut line_width: usize = 0;
    let mut i: usize = 0;
    let mut first_line = true;

    while i < symbols.len() {
        let space_start = i;
        while i < symbols.len() && symbols[i].ch == ' ' {
            i += 1;
        }
        let spaces = &symbols[space_start..i];
        if i >= symbols.len() {
            // Trailing spaces.
            for sp in spaces {
                if line_width >= width && !line.is_empty() {
                    lines.push(std::mem::take(&mut line));
                    line_width = 0;
                    first_line = false;
                }
                line.push(sp.clone());
                line_width += 1;
            }
            break;
        }
        let word_start = i;
        while i < symbols.len() && symbols[i].ch != ' ' {
            i += 1;
        }
        let word = &symbols[word_start..i];
        let word_width: usize = word.iter().map(|s| s.width()).sum();

        if line.is_empty() {
            if first_line && !spaces.is_empty() {
                // At most one leading space survives at the very
                // start of the prompt.
                line.push(spaces[0].clone());
                line_width = 1;
            }
            add_split_word(word, width, &mut lines, &mut line, &mut line_width);
            if !lines.is_empty() {
                first_line = false;
            }
        } else if line_width + spaces.len() + word_width <= width {
            line.extend(spaces.iter().cloned());
            line.extend(word.iter().cloned());
            line_width += spaces.len() + word_width;
        } else {
            lines.push(std::mem::take(&mut line));
            line_width = 0;
            first_line = false;
            add_split_word(word, width, &mut lines, &mut line, &mut line_width);
        }
    }
    if !line.is_empty() || lines.is_empty() {
        lines.push(line);
    }
    lines
}

fn draw_symbols(buffer: &mut Buffer, rect: Rect, lines: &[Vec<Symbol>]) {
    for (row, line) in lines.iter().enumerate() {
        if row as u16 >= rect.height {
            break;
        }
        let y = rect.y + row as u16;
        let mut x = rect.x;
        let mut run_style: Option<Style> = None;
        let mut run = String::new();
        let mut run_start = x;
        for sym in line {
            if run_style != Some(sym.style) {
                if let Some(style) = run_style {
                    if !run.is_empty() {
                        buffer.set_stringn(run_start, y, &run, style, rect.right());
                    }
                }
                run_style = Some(sym.style);
                run_start = x;
                run = String::new();
            }
            run.push_str(&sym.text);
            x += sym.width() as u16;
        }
        if let Some(style) = run_style {
            if !run.is_empty() {
                buffer.set_stringn(run_start, y, &run, style, rect.right());
            }
        }
    }
}

fn draw_test(buffer: &mut Buffer, test: &Test) {
    let frame_w = buffer.width;
    let frame_h = buffer.height;
    let max_width = frame_w.saturating_sub(10);
    let prompt_width = unicode_width_str(&test.prompt);
    let area_width = (prompt_width.min(max_width as usize)) as u16;

    let estimated_lines: usize = if max_width == 0 || prompt_width == 0 {
        0
    } else {
        (prompt_width + max_width as usize - 1) / max_width as usize
    };
    let estimated_height: usize = if estimated_lines <= 1 {
        1
    } else {
        estimated_lines + 1
    };
    let area_x = frame_w / 2 - area_width / 2;
    let area_y: u16 = if estimated_height >= frame_h as usize {
        0
    } else {
        (frame_h - estimated_height as u16) / 2
    };
    let area_height: u16 = {
        let h = u16::try_from(estimated_height).unwrap_or(u16::MAX);
        h.min(frame_h.saturating_sub(area_y))
    };

    let mut prompt_y = area_y;
    if let Some(remaining) = test.secs_remaining {
        let timer = format!("{:.1}", remaining);
        let timer_width = unicode_width_str(&timer) as u16;
        let timer_x = (frame_w / 2).saturating_sub(timer_width / 2);
        buffer.set_string(timer_x, area_y, &timer, Style::new().bold().dim());
        prompt_y = area_y.saturating_add(2);
    }

    if area_width == 0 {
        return;
    }
    let symbols = prompt_symbols(test);
    let lines = wrap_symbols(&symbols, area_width);
    let rect = Rect {
        x: area_x,
        y: prompt_y,
        width: area_width,
        height: {
            let below = frame_h.saturating_sub(prompt_y);
            area_height.min(below)
        },
    };
    draw_symbols(buffer, rect, &lines);
}

