    let bold = Style::new().bold();
    let bottom_label_y = graph.y + graph.height - 1;
    buffer.set_stringn(
        area.x,
        bottom_label_y,
        y_bottom_label,
        bold,
        area.x + label_width,
    );
    buffer.set_stringn(area.x, area.y, &y_top_label, bold, area.x + label_width);

    let x_labels_y = x_axis_y + 1;
    if x_labels_y < area.bottom() {
        buffer.set_string(axis_x, x_labels_y, "1", bold);
        let last = format!("{:.2}", results.x_max);
        let last_w = unicode_width_str(&last) as u16;
        if area.right() >= last_w {
            buffer.set_string(area.right() - last_w, x_labels_y, &last, bold);
        }
    }

    // Axis titles.
    buffer.set_stringn(graph.x, graph.y, "wpm", Style::new(), graph.right());
    let seconds = "seconds";
    let sec_w = unicode_width_str(seconds) as u16;
    if graph.right() >= sec_w {
        buffer.set_string(
            graph.right() - sec_w,
            bottom_label_y,
            seconds,
            Style::new(),
