fn draw_results(buffer: &mut Buffer, results: &Results) {
    let frame_w = buffer.width;
    let frame_h = buffer.height;
    let content = Rect {
        x: 5.min(frame_w),
        y: 2.min(frame_h),
        width: frame_w.saturating_sub(10),
        height: frame_h.saturating_sub(4),
    };
    if content.width == 0 || content.height == 0 {
        return;
    }
    let chart_height = content.height.saturating_sub(3);
    let chart = Rect {
        height: chart_height,
        ..content
    };
    draw_chart(buffer, chart, results);

    let summary_y = content.y + chart_height;
    if summary_y < frame_h {
        let summary = format!(
            "{} wpm   {}% acc   {:.2} sd",
            results.wpm, results.accuracy, results.std_dev
        );
        let text_w = unicode_width_str(&summary) as u16;
        let x = if text_w > content.width {
            content.x
        } else {
            (frame_w / 2).saturating_sub(text_w / 2)
        };
        buffer.set_stringn(
            x,
            summary_y,
            &summary,
            Style::new().bold(),
            content.right(),
        );
    }

    let retry_y = summary_y.saturating_add(2);
    if retry_y < frame_h {
        buffer.set_stringn(
            content.x,
            retry_y,
            "(r)etry / (n)ew / (esc)ape",
            Style::new().italic(),
            content.right(),
        );
    }
}

pub fn draw(buffer: &mut Buffer, app: &App) {
    if app.test.is_complete() {
        let results = app.display_results();
        draw_results(buffer, &results);
    } else {
        draw_test(buffer, &app.test);
    }
}
