    };

    let mut prompt_y = area_y;
    if let Some(remaining) = test.secs_remaining {
        let timer = format!("{:.1}", remaining);
        let timer_width = unicode_width_str(&timer) as u16;
        let timer_x = (frame_w / 2).saturating_sub(timer_width / 2);
        buffer.set_string(timer_x, area_y, &timer, Style::new().bold().dim());
        prompt_y = area_y.saturating_add(2);
    }

    if area_width == 0 {
        return;
    }
    let symbols = prompt_symbols(test);
    let lines = wrap_symbols(&symbols, area_width);
    let rect = Rect {
        x: area_x,
        y: prompt_y,
        width: area_width,
        height: {
            let below = frame_h.saturating_sub(prompt_y);
            area_height.min(below)
        },
    };
    draw_symbols(buffer, rect, &lines);
}

