fn bresenham(x0: i32, y0: i32, x1: i32, y1: i32, plot: &mut impl FnMut(i32, i32)) {
    let dx = (x1 - x0).abs();
    let sx = if x0 < x1 { 1 } else { -1 };
    let dy = -(y1 - y0).abs();
    let sy = if y0 < y1 { 1 } else { -1 };
    let mut err = dx + dy;
    let (mut x, mut y) = (x0, y0);
    loop {
        plot(x, y);
        if x == x1 && y == y1 {
            break;
        }
        let e2 = 2 * err;
        if e2 >= dy {
            err += dy;
            x += sx;
        }
        if e2 <= dx {
            err += dx;
            y += sy;
        }
    }
}

fn draw_chart(buffer: &mut Buffer, area: Rect, results: &Results) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let y_top_label = format!("{:.0}", results.y_max);
    let y_bottom_label = "0";
    let label_width = unicode_width_str(&y_top_label)
        .max(unicode_width_str(y_bottom_label)) as u16;
    if label_width >= area.width {
        return;
    }
    let axis_x = area.x + label_width;
    let graph = Rect {
        x: axis_x + 1,
        y: area.y,
        width: area.width - label_width - 1,
        height: area.height.saturating_sub(2),
    };
    if graph.width == 0 || graph.height == 0 {
        return;
    }

    // --- dataset, as a braille line plot -------------------------------
    let grid_w = graph.width as i32 * 2;
    let grid_h = graph.height as i32 * 4;
    let mut dots = vec![false; (grid_w.max(0) * grid_h.max(0)) as usize];
    let plot_dot = |dots: &mut Vec<bool>, gx: i32, gy: i32| {
        if gx >= 0 && gx < grid_w && gy >= 0 && gy < grid_h {
            dots[(gy * grid_w + gx) as usize] = true;
        }
    };
    let map_point = |x: f64, y: f64| -> Option<(i32, i32)> {
        if !x.is_finite() || !y.is_finite() || !results.y_max.is_finite() {
            return None;
        }
        if x < 1.0 || x > results.x_max || y < 0.0 || y > results.y_max {
            return None;
        }
        let gx = if results.x_max <= 1.0 || grid_w <= 1 {
            0
        } else {
            ((x - 1.0) / (results.x_max - 1.0) * (grid_w - 1) as f64).round() as i32
        };
        let gy_from_bottom = if results.y_max <= 0.0 || grid_h <= 1 {
            0
        } else {
            (y / results.y_max * (grid_h - 1) as f64).round() as i32
        };
        Some((gx, grid_h - 1 - gy_from_bottom))
    };

    let mapped: Vec<(i32, i32)> = results
        .points
        .iter()
        .filter_map(|&(x, y)| map_point(x, y))
        .collect();
    if mapped.len() == 1 {
        plot_dot(&mut dots, mapped[0].0, mapped[0].1);
    }
    for pair in mapped.windows(2) {
        let (x0, y0) = pair[0];
        let (x1, y1) = pair[1];
        let mut dots_ref = &mut dots;
        bresenham(x0, y0, x1, y1, &mut |gx, gy| {
            if gx >= 0 && gx < grid_w && gy >= 0 && gy < grid_h {
                dots_ref[(gy * grid_w + gx) as usize] = true;
            }
        });
    }

    // Braille dot bit for (dx, dy) within a cell.
    let braille_bit = |dx: i32, dy: i32| -> u32 {
        match (dx, dy) {
            (0, 0) => 0x01,
            (0, 1) => 0x02,
            (0, 2) => 0x04,
            (0, 3) => 0x40,
            (1, 0) => 0x08,
            (1, 1) => 0x10,
            (1, 2) => 0x20,
            (1, 3) => 0x80,
            _ => 0,
        }
    };
    for cy in 0..graph.height {
        for cx in 0..graph.width {
            let mut bits: u32 = 0;
            for dy in 0..4i32 {
                for dx in 0..2i32 {
                    let gx = cx as i32 * 2 + dx;
                    let gy = cy as i32 * 4 + dy;
                    if dots[(gy * grid_w + gx) as usize] {
                        bits |= braille_bit(dx, dy);
                    }
                }
            }
            if bits != 0 {
                if let Some(symbol) = char::from_u32(0x2800 + bits) {
                    // Cells on the first row of the graph keep the
                    // default colour in the reference; the rest of
                    // the line is magenta.
                    let style = if cy == 0 {
                        Style::new()
                    } else {
                        Style::new().fg(Color::Magenta)
                    };
                    buffer.set_cell(
                        graph.x + cx,
                        graph.y + cy,
                        &symbol.to_string(),
                        style,
                    );
                }
            }
        }
    }

    // --- axes -------------------------------------------------------------
    for row in 0..graph.height {
        buffer.set_cell(axis_x, graph.y + row, "│", Style::new());
    }
    let x_axis_y = graph.y + graph.height;
    if x_axis_y < area.bottom() {
        buffer.set_cell(axis_x, x_axis_y, "└", Style::new());
        for x in graph.x..graph.right() {
            buffer.set_cell(x, x_axis_y, "─", Style::new());
        }
    }

    // --- labels and titles (drawn over the dataset) ----------------------
    let bold = Style::new().bold();
    let bottom_label_y = graph.y + graph.height - 1;
    buffer.set_stringn(
        area.x,
        bottom_label_y,
        y_bottom_label,
        bold,
        area.x + label_width,
    );
    buffer.set_stringn(area.x, area.y, &y_top_label, bold, area.x + label_width);

    let x_labels_y = x_axis_y + 1;
    if x_labels_y < area.bottom() {
        buffer.set_string(axis_x, x_labels_y, "1", bold);
        let last = format!("{:.2}", results.x_max);
        let last_w = unicode_width_str(&last) as u16;
        if area.right() >= last_w {
            buffer.set_string(area.right() - last_w, x_labels_y, &last, bold);
        }
    }

    // Axis titles.
    buffer.set_stringn(graph.x, graph.y, "wpm", Style::new(), graph.right());
    let seconds = "seconds";
    let sec_w = unicode_width_str(seconds) as u16;
    if graph.right() >= sec_w {
        buffer.set_string(
            graph.right() - sec_w,
            bottom_label_y,
            seconds,
            Style::new(),
        );
    }
}

fn draw_results(buffer: &mut Buffer, results: &Results) {
    let frame_w = buffer.width;
    let frame_h = buffer.height;
    let content = Rect {
        x: 5.min(frame_w),
