mod app;
mod cli;
mod log;
mod prompt;
mod terminal;
mod ui;

use app::{Action, App};
use std::io::{self, IsTerminal, Write};
use std::time::{Duration, Instant};
use terminal::{terminal_size, Buffer, InputParser, RawTerminal, Renderer};

fn draw_frame(
    renderer: &mut Renderer,
    out: &mut impl Write,
    app: &App,
) -> io::Result<(u16, u16)> {
    let (width, height) = terminal_size();
    let mut buffer = Buffer::new(width, height);
    ui::draw(&mut buffer, app);
    renderer.draw(out, &buffer)?;
    Ok((width, height))
}

fn run(args: cli::Args) -> io::Result<()> {
    let mut stdout = io::stdout().lock();
    let mut raw = RawTerminal::enable()?;
    stdout.write_all(b"\x1b[?1049h")?;
    stdout.flush()?;

    let mut app = App::new(args);
    let mut renderer = Renderer::new();
    let mut last_size = draw_frame(&mut renderer, &mut stdout, &app)?;

    let mut input = InputParser::new();
    let tick = Duration::from_millis(100);
    let mut next_tick = Instant::now() + tick;

    'main: loop {
        // Process every complete key already in the buffer first.
        if let Some(key) = input.next_key() {
            if app.handle_key(key) == Action::Quit {
                break 'main;
            }
            last_size = draw_frame(&mut renderer, &mut stdout, &app)?;
            continue;
        }

        let now = Instant::now();
        let timeout_ms: i32 = if now >= next_tick {
            0
        } else {
            (next_tick - now).as_millis().min(i32::MAX as u128) as i32
        };
        if InputParser::poll_readable(timeout_ms) {
            if !input.fill() {
                break 'main;
            }
            continue;
        }

        let now = Instant::now();
        if now >= next_tick {
            next_tick = now + tick;
            let tick_draw = app.on_tick(now);
            let size = terminal_size();
            if tick_draw || size != last_size {
                last_size = draw_frame(&mut renderer, &mut stdout, &app)?;
            }
        }
    }

    stdout.write_all(b"\x1b[?1049l\x1b[?25h")?;
    stdout.flush()?;
    raw.disable();
    Ok(())
}

fn main() {
    let args = cli::parse();
    if !io::stdin().is_terminal() {
        eprint!(
            "error: stdin must be a tty\n\nUSAGE:\n    thokr [OPTIONS]\n\nFor more information try --help\n"
        );
        std::process::exit(2);
    }
    match run(args) {
        Ok(()) => {}
        Err(err) => {
            eprintln!("Error: {:?}", err);
            std::process::exit(1);
        }
    }
}
