{"command":"cat <<'PY' > /tmp/compare_tui.py
import sys; sys.path.insert(0,'/tmp'); from helper import Tmux
import subprocess,time,re,os,shutil
REF="/tmp/refbin/executable"; MINE="/tmp/mybin/executable"
def run_capture(prog,args,w=80,h=24,actions=[]):
    home="/tmp/cmp_home"
    if os.path.exists(home): shutil.rmtree(home)
    os.makedirs(home)
    # quote simple args in tests manually via command string supplied by caller instead
    t=Tmux(cmd=f"{prog} {args}",home=home,w=w,h=h)
    caps=[t.cap(True)]
    for a in actions:
        if a.startswith("key:"): t.send(a[4:],delay=0.25)
        elif a.startswith("text:"):
            for ch in a[5:]:
                if ch==" ": t.send("Space",delay=0.04)
                else: subprocess.run(["tmux","send-keys","-t",t.sess,"-l",ch]); time.sleep(0.04)
            time.sleep(0.25)
        elif a=="wait": time.sleep(0.5)
        caps.append(t.cap(True))
    log=None
    p=os.path.join(home,".config/thokr/log.csv")
    if os.path.exists(p):
        # strip date and elapsed for summary comparisons externally if needed
        log=open(p).read()
    alive=t.alive()
    try:t.send("Escape",delay=0.15)
    except:pass
    t.kill(); subprocess.run(["tmux","kill-server"],capture_output=True); time.sleep(0.08)
    return caps,log,alive

def compare(args,w=80,h=24,actions=[],label=""):
    a,alog,aalive=run_capture(REF,args,w,h,actions)
    b,blog,balive=run_capture(MINE,args,w,h,actions)
    if a!=b:
        print("\nDIFF CAP",label,args,w,h,actions)
        for i,(x,y) in enumerate(zip(a,b)):
            if x!=y:
                print(" step",i)
                print(" REF",repr(x))
                print(" MINE",repr(y))
    else:
        print("OK CAP",label)
    # log compare excluding date/elapsed (cols)
    def norm(log):
        if not log:return None
        out=[]
        for line in log.splitlines():
            parts=line.split(",")
            if len(parts)>=7: out.append(tuple(parts[1:3]+parts[4:]))
            else: out.append(line)
        return out
    if norm(alog)!=norm(blog):
        print("DIFF LOG",label,"ref",alog,"mine",blog)
    else:
        print("OK LOG",label)
