import sys; sys.path.insert(0,'/tmp'); from compare_tui2 import run_schedule,REF,MINE
import re
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def points(cap):
    lines=strip(cap).splitlines()
    pts=[]
    # graph x starts depends y label: find axis char row2; axis col index
    axis=lines[2].index('│')
    gx0=axis+1
    bitsmap={(0,0):1,(0,1):2,(0,2):4,(0,3):64,(1,0):8,(1,1):16,(1,2):32,(1,3):128}
    inv={v:k for k,v in bitsmap.items()}
    for r in range(2,17):
        line=lines[r] if r<len(lines) else ''
        for col,ch in enumerate(line):
            if 0x2800 <= ord(ch) <= 0x28ff:
                bits=ord(ch)-0x2800
                for b,(dx,dy) in inv.items():
                    if bits & b: pts.append(((col-gx0)*2+dx,(r-2)*4+dy,col-gx0,r-2))
    return sorted(pts)
def analyze(label,prompt,items):
    for name,prog in [('REF',REF),('MINE',MINE)]:
        cap,log=run_schedule(prog,prompt,items)
        pts=points(cap)
        print(label,name,"npts",len(pts),"xrange",min(p[0] for p in pts),max(p[0] for p in pts),"yrange",min(p[1] for p in pts),max(p[1] for p in pts))
        # y at selected x ranges (min/max)
        for xlo in range(0,140,10):
            ys=[p[1] for p in pts if xlo <= p[0] < xlo+10]
            if ys: print(f"  x{xlo:3d}: y{min(ys)}-{max(ys)}")
        # cells list
        cells=sorted(set((p[2],p[3]) for p in pts))
        print(" cells by row")
        for row in sorted(set(c[1] for c in cells)):
            cs=[c[0] for c in cells if c[1]==row]; print("  row",row,min(cs),max(cs),len(cs))
