import sys; sys.path.insert(0,'/tmp')
from compare_tui2 import run_schedule,schedule_typed,REF,MINE
import re
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def get_points(prog,prompt,items):
 cap,log=run_schedule(prog,prompt,items); lines=strip(cap).splitlines(); axis=lines[2].index('│'); gx0=axis+1
 bits={(0,0):1,(0,1):2,(0,2):4,(0,3):64,(1,0):8,(1,1):16,(1,2):32,(1,3):128}; inv={v:k for k,v in bits.items()}; pts=set()
 for r in range(2,17):
  line=lines[r] if r<len(lines) else ''
  for col,ch in enumerate(line):
   if 0x2800<=ord(ch)<=0x28ff:
    b=ord(ch)-0x2800
    for bit,(dx,dy) in inv.items():
     if b&bit: pts.add(((col-gx0)*2+dx,(r-2)*4+dy))
 return pts

def current_bres(x0,y0,x1,y1):
 pts=[]; dx=abs(x1-x0); sx=1 if x0<x1 else -1; dy=-abs(y1-y0); sy=1 if y0<y1 else -1; err=dx+dy; x,y=x0,y0
 while True:
  pts.append((x,y))
  if x==x1 and y==y1:break
  e2=2*err
  if e2>=dy:err+=dy;x+=sx
  if e2<=dx:err+=dx;y+=sy
 return pts

def lowhigh(x0,y0,x1,y1):
 pts=[]
 if abs(y1-y0)<abs(x1-x0):
  if x0>x1:return list(reversed(lowhigh(x1,y1,x0,y0)))
  dx=x1-x0; dy=y1-y0; yi=1
  if dy<0:yi=-1;dy=-dy
  D=2*dy-dx; y=y0
  for x in range(x0,x1+1):
   pts.append((x,y))
   if D>0:y+=yi;D-=2*dx
   D+=2*dy
 else:
  if y0>y1:return list(reversed(lowhigh(x1,y1,x0,y0)))
  dx=x1-x0; dy=y1-y0; xi=1
  if dx<0:xi=-1;dx=-dx
  D=2*dx-dy; x=x0
  for y in range(y0,y1+1):
   pts.append((x,y))
   if D>0:x+=xi;D-=2*dy
   D+=2*dx
 return pts

def interp_round(x0,y0,x1,y1,mode='round'):
 pts=[]
 steps=max(abs(x1-x0),abs(y1-y0))
 if steps==0:return [(x0,y0)]
 import math
 for i in range(steps+1):
  x=x0+(x1-x0)*i/steps; y=y0+(y1-y0)*i/steps
  if mode=='round':pts.append((math.floor(x+0.5),math.floor(y+0.5)))
  elif mode=='floor':pts.append((math.floor(x),math.floor(y)))
 return pts

def linedrawing(x0,y0,x1,y1):
 # A variant often in line_drawing crate: iterate main axis, accumulate error using dy/dx after plotting perhaps
 pts=[]; dx=x1-x0; dy=y1-y0; xsign=1 if dx>0 else -1 if dx<0 else 0; ysign=1 if dy>0 else -1 if dy<0 else 0
 dx=abs(dx); dy=abs(dy)
 # swap if steep, remembering point axes
 steep=dy>dx
 if steep: dx,dy=dy,dx
 err=0; x,y=x0,y0
 for i in range(dx+1):
  pts.append((x,y))
  err+=dy
  if err>=dx:
   err-=dx
   if steep:x+=xsign
   else:y+=ysign
  if steep:y+=ysign
  else:x+=xsign
 return pts

def render(points,fn):
 out=set()
 for a,b in zip(points,points[1:]): out.update(fn(*a,*b))
 if len(points)==1:out.add(points[0])
 return out

