 ref=get_points(REF,prompt,items)
 # remove points overwritten by title in first 3 graph cells: x<6 and y<4 (top row wpm) from both ref/candidates by filtering candidate same
 def filt(s): return {(x,y) for x,y in s if not (x<6 and y<4)}
