   pts.append((x,y))
   if D>0:x+=xi;D-=2*dy
   D+=2*dx
 return pts

def interp_round(x0,y0,x1,y1,mode='round'):
 pts=[]
 steps=max(abs(x1-x0),abs(y1-y0))
 if steps==0:return [(x0,y0)]
 import math
 for i in range(steps+1):
  x=x0+(x1-x0)*i/steps; y=y0+(y1-y0)*i/steps
  if mode=='round':pts.append((math.floor(x+0.5),math.floor(y+0.5)))
  elif mode=='floor':pts.append((math.floor(x),math.floor(y)))
 return pts

def linedrawing(x0,y0,x1,y1):
 # A variant often in line_drawing crate: iterate main axis, accumulate error using dy/dx after plotting perhaps
 pts=[]; dx=x1-x0; dy=y1-y0; xsign=1 if dx>0 else -1 if dx<0 else 0; ysign=1 if dy>0 else -1 if dy<0 else 0
 dx=abs(dx); dy=abs(dy)
 # swap if steep, remembering point axes
 steep=dy>dx
 if steep: dx,dy=dy,dx
 err=0; x,y=x0,y0
 for i in range(dx+1):
  pts.append((x,y))
  err+=dy
  if err>=dx:
   err-=dx
   if steep:x+=xsign
   else:y+=ysign
  if steep:y+=ysign
  else:x+=xsign
 return pts

