    if graph.width == 0 || graph.height == 0 {
        return;
    }
"""
new = """    let y_top_label = format!(\"{:.0}\", results.y_max);
    let y_bottom_label = \"0\";
    let max_label_width = unicode_width_str(&y_top_label)
        .max(unicode_width_str(y_bottom_label)) as u16;
    let label_width = max_label_width.min(area.width / 3);
    let axis_x = area.x + label_width;
    let graph_height = if area.height <= 2 {
        1
    } else {
        area.height - 2
    };
    let graph = Rect {
        x: axis_x + 1,
        y: area.y,
        width: area.width.saturating_sub(label_width + 1),
        height: graph_height,
    };
    if graph.width == 0 {
        // Still draw whatever of the axes fits.
        if axis_x < area.right() {
            for row in 0..graph.height {
                buffer.set_cell(axis_x, graph.y + row, \"│\", Style::new());
            }
        }
        return;
    }
"""
assert old in s; s=s.replace(old,new)
# Dataset style always magenta (title handling below resets top row)
old2 = """                    // Cells on the first row of the graph keep the
                    // default colour in the reference; the rest of
                    // the line is magenta.
                    let style = if cy == 0 {
                        Style::new()
                    } else {
                        Style::new().fg(Color::Magenta)
                    };
"""
new2 = """                    let style = Style::new().fg(Color::Magenta);
"""
assert old2 in s; s=s.replace(old2,new2)
# Replace axes/labels/titles block
start=s.index("    // --- axes -------------------------------------------------------------")
end=s.index("\nfn draw_results",start)
new_block='''    // --- axes -------------------------------------------------------------
    for row in 0..graph.height {
        buffer.set_cell(axis_x, graph.y + row, "│", Style::new());
    }
    let x_axis_y = graph.y + graph.height;
    if area.height >= 3 && x_axis_y < area.bottom() {
        buffer.set_cell(axis_x, x_axis_y, "└", Style::new());
        for x in graph.x..graph.right() {
            buffer.set_cell(x, x_axis_y, "─", Style::new());
        }
    }

    // --- labels and titles (drawn over the dataset) ----------------------
    let bold = Style::new().bold();
    let bottom_label_y = graph.y + graph.height - 1;
    buffer.set_stringn(
        area.x,
        bottom_label_y,
        y_bottom_label,
        bold,
        area.x + label_width,
    );
    buffer.set_stringn(area.x, area.y, &y_top_label, bold, area.x + label_width);

    let x_labels_y = if area.height >= 3 {
        Some(x_axis_y + 1)
    } else if area.height == 2 {
        Some(graph.y + 1)
    } else {
        None
    };
    if let Some(x_labels_y) = x_labels_y {
        if x_labels_y < area.bottom() {
            buffer.set_string(axis_x, x_labels_y, "1", bold);
            let last = format!("{:.2}", results.x_max);
            let last_w = unicode_width_str(&last) as u16;
            let slot_start = graph.x + (graph.width + 1) / 2;
            if slot_start < graph.right() {
                let slot_width = graph.right() - slot_start;
                let start_x = if last_w <= slot_width {
                    graph.right() - last_w
                } else {
                    slot_start
                };
                buffer.set_stringn(start_x, x_labels_y, &last, bold, graph.right());
            }
        }
    }

    // Axis titles are only shown when the graph is tall and wide
    // enough.  Drawing the y-axis title also restyles the whole
    // top graph row back to the default style.
    if graph.height >= 3 {
        if graph.width >= 5 {
            for x in graph.x..graph.right() {
                let idx = buffer.index(x, graph.y);
                buffer.cells[idx].style = Style::new();
            }
            buffer.set_stringn(graph.x, graph.y, "wpm", Style::new(), graph.right());
        }
        if graph.width >= 8 {
            let seconds = "seconds";
            let sec_w = unicode_width_str(seconds) as u16;
            buffer.set_string(
                graph.right() - sec_w,
                bottom_label_y,
                seconds,
                Style::new(),
            );
        }
    }
}
'''
s=s[:start]+new_block+s[end:]
# Results layout small heights / clipping
