"""
new3="""    let chart_height = if content.height <= 3 {
        content.height.min(1)
    } else {
        content.height - 3
    };
"""
assert old3 in s; s=s.replace(old3,new3)
s=s.replace("    let summary_y = content.y + chart_height;\n    if summary_y < frame_h {", "    let summary_y = content.y + chart_height;\n    if summary_y < content.bottom() {")
s=s.replace("    let retry_y = summary_y.saturating_add(2);\n    if retry_y < frame_h {", "    let retry_y = summary_y.saturating_add(2);\n    if retry_y < content.bottom() {")
