p='src/ui.rs'; s=open(p).read()
insert="""///
/// The prompt is rendered as a single logical line consisting of
/// three runs:
///
/// * the characters typed so far, coloured according to whether
///   each one matches the prompt at that position;
/// * the single character at the cursor, shown underlined; and
/// * the remainder of the prompt, which has not been typed yet.
///
/// A mistyped space would ordinarily be invisible, so it is shown
/// as a middle dot instead.  Every other mistyped position shows
/// the prompt's character (coloured as an error) rather than the
/// character that was actually typed, which keeps the prompt
/// itself readable at all times.  Styles therefore travel with
/// each symbol through the word-wrapping step below.
"""
assert insert.count('\n')==16, insert.count('\n')
s=s.replace("fn prompt_symbols(", insert+"fn prompt_symbols(",1)
s=s.replace("        let current = &test.prompt[index..index + 1];\n        for ch in current.chars() {", "        let curr = &test.prompt[index..index + 1];\n        for ch in curr.chars() {")
open(p,'w').write(s)
PY
nl -ba src/ui.rs | sed -n '85,100p'
cargo build --release --offline -q && cp target/release/thokr /tmp/myexe
python3 - << 'PY'
import pty,os,time,select,fcntl,termios,struct
for prog in ['/tmp/refbin/executable','/tmp/mybin/executable']:
 pid,fd=pty.fork()
 if pid==0:
  os.environ['TERM']='xterm'; os.environ['HOME']='/tmp/ptyhome'; os.execv(prog,[prog,'-p','é'])
 fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack('HHHH',24,80,0,0)); time.sleep(.4); data=b''
 while select.select([fd],[],[],.1)[0]:
  d=os.read(fd,65536); data+=d
 wpid,st=os.waitpid(pid,os.WNOHANG); print(prog,os.waitstatus_to_exitcode(st) if wpid else None,repr(data))
PY"}

