{"command":"cat <<'PY' > /tmp/check_random.py
import sys; sys.path.insert(0,'/tmp'); from helper import Tmux
import subprocess,time,re,collections,json
def strip(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def get(prog,args,w=300,h=80):
 t=Tmux(cmd=f"{prog} {args}",w=w,h=h)
 lines=[l.strip() for l in strip(t.cap(True)).splitlines() if l.strip()]
 txt=' '.join(lines)
 t.kill(); subprocess.run(['tmux','kill-server'],capture_output=True); time.sleep(.08)
 return txt

pools={lang:set(json.load(open(f'/tmp/{lang}_union.json'))) for lang in ['english','english1k','english10k']}
for prog in ['/tmp/refbin/executable','/tmp/mybin/executable']:
 print('\n',prog)
 for lang,n in [('english',15),('english',200),('english',300),('english1k',100),('english1k',2000),('english10k',100)]:
  txt=get(prog,f"-w {n} -l {lang}"); words=txt.split(); print(lang,n,len(words),len(set(words)),'allinpool',set(words)<=pools[lang],words[:8])
 for f in [1,3,10]:
  txt=get(prog,f"-f {f}"); sents=[s.strip() for s in txt.split('.') if s.strip()]; print('f',f,'sentences',len(sents),'endsdot',txt.endswith('.'),'wordcounts',sorted(collections.Counter(len(s.split()) for s in sents).items())); print(' ',txt[:300])
