{"command":"cat <<'PY' > /tmp/compare_log.py
import subprocess,time,os,shutil
def run(prog,env,setup=None, typed="ab", args="-p 'ab'"):
    subprocess.run(["tmux","kill-server"],capture_output=True); time.sleep(.08)
    if setup: setup()
    sess="probe"; a=["tmux","new-session","-d","-s",sess,"-x","80","-y","24"]
    for k,v in env.items(): a+=["-e",f"{k}={v}"]
    a.append(f"{prog} {args}")
    subprocess.run(a,capture_output=True); time.sleep(.5)
    for ch in typed:
        if ch==' ': subprocess.run(["tmux","send-keys","-t",sess,"Space"])
        else: subprocess.run(["tmux","send-keys","-t",sess,"-l",ch])
        time.sleep(.05)
    time.sleep(.3)
    files={}
    for base in ["/tmp/logA","/tmp/logB"]:
        for root,dirs,fs in os.walk(base):
            for f in fs:
                p=os.path.join(root,f); files[p.replace(base,'BASE')]=open(p).read()
    subprocess.run(["tmux","kill-server"],capture_output=True)
    # Normalize date and elapsed first fields in csv rows
    norm={}
    for k,v in files.items():
        lines=[]
        for line in v.splitlines(True):
            parts=line.rstrip('\n').split(',')
            if len(parts)>=7 and parts[1].isdigit(): lines.append(','.join(['DATE']+parts[1:3]+['ELAP']+parts[4:])+'\n')
            else: lines.append(line)
        norm[k]=''.join(lines)
    return norm

def clean():
    shutil.rmtree("/tmp/logA",ignore_errors=True); shutil.rmtree("/tmp/logB",ignore_errors=True); os.makedirs("/tmp/logA"); os.makedirs("/tmp/logB")
def setup_empty():
    clean(); os.makedirs("/tmp/logA/.config/thokr",exist_ok=True); open("/tmp/logA/.config/thokr/log.csv",'w').close()
def setup_custom():
    clean(); os.makedirs("/tmp/logA/.config/thokr",exist_ok=True); open("/tmp/logA/.config/thokr/log.csv",'w').write("custom,no-newline")
def setup_fileblock():
    clean(); os.makedirs("/tmp/logA/.config",exist_ok=True); open("/tmp/logA/.config/thokr",'w').write("not dir")
def setup_logdir():
    clean(); os.makedirs("/tmp/logA/.config/thokr/log.csv",exist_ok=True)
def cmp(label, env, setup, typed="ab",args="-p 'ab'"):
    # Use logA for both but reset setup between runs; then normalize base in run uses both logA/logB - setup only A. env points to A for ref and A for mine after reset.
    setup(); a=run('/tmp/refbin/executable',env,None,typed,args)
    setup(); b=run('/tmp/mybin/executable',env,None,typed,args)
    print('OK' if a==b else 'DIFF',label)
    if a!=b: print(' ref',a); print(' mine',b)

E={"HOME":"/tmp/logA","XDG_CONFIG_HOME":"/tmp/logA/.config"}
for label,setup in [('fresh',clean),('empty',setup_empty),('custom',setup_custom),('fileblock',setup_fileblock),('logdir',setup_logdir)]:
    cmp(label,E,setup)
cmp('xdg precedence',{"HOME":"/tmp/logA","XDG_CONFIG_HOME":"/tmp/logB"},clean)
cmp('relative xdg',{"HOME":"/tmp/logA","XDG_CONFIG_HOME":"rel"},clean)
cmp('timer fields',E,clean,args="-p 'ab' -s 9")
cmp('full fields',E,clean,args="-p 'ab' -f 2")
cmp('words fields',E,clean,args="-p 'ab' -w 7")
PY
