import pty,os,time,select,fcntl,termios,struct
def run(prog,args,cols,rows=50):
 pid,fd=pty.fork()
 if pid==0:
  os.environ['TERM']='xterm';os.execv(prog,[prog]+args)
 fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack('HHHH',rows,cols,0,0));time.sleep(.3);d=b''
 while select.select([fd],[],[],.1)[0]:
  try:x=os.read(fd,65536)
  except:break
  if not x:break
  d+=x
 os.waitpid(pid,0);return d
for cols in [20,30,40,60,80,100,200]:
 a=run('/tmp/refbin/executable',['--help'],cols); b=run('/tmp/mybin/executable',['--help'],cols)
 print(cols, a==b, len(a), len(b))
 if a!=b: print(a.decode()); print('---mine---'); print(b.decode())
PY"}

