{"command":"cat <<'PY' > /tmp/pty_cli.py
import pty,os,time,select,fcntl,termios,struct,re
def run(prog,args,cols=80,rows=50,env=None):
 pid,fd=pty.fork()
 if pid==0:
  os.environ['TERM']='xterm-256color'
  if env:
   for k,v in env.items():
    if v is None: os.environ.pop(k,None)
    else: os.environ[k]=v
  os.execv(prog,[prog]+args)
 fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack('HHHH',rows,cols,0,0));time.sleep(.3);d=b''
 while True:
  r,_,_=select.select([fd],[],[],.1)
  if not r:break
  try:x=os.read(fd,65536)
  except:break
  if not x:break
  d+=x
 _,st=os.waitpid(pid,0);os.close(fd)
 return os.waitstatus_to_exitcode(st),d
def strip(b): return re.sub(rb'\x1b\[[0-9;]*m',b'',b)
