}''','''struct Parser {
    bin: String,
    display: String,
    occurrences: Vec<Occurrence>,
    color_stdout: bool,
    color_stderr: bool,
}

/// Whether clap-style coloured output should be used on a stream.
fn color_enabled(stream_is_tty: bool) -> bool {
    stream_is_tty
        && std::env::var_os("NO_COLOR").is_none()
        && matches!(std::env::var_os("TERM"), Some(v) if v != "dumb")
}

const RESET: &str = "\\x1b[0m";
const GREEN: &str = "\\x1b[32m";
const YELLOW: &str = "\\x1b[33m";

fn seg_end() -> String {
    format!("{RESET}{RESET}")
}
fn seg_default(text: &str) -> String {
    format!("{RESET}{RESET}{text}")
}
fn seg_yellow(text: &str) -> String {
    format!("{RESET}{RESET}{YELLOW}{text}")
}
fn seg_green(text: &str) -> String {
    format!("{RESET}{RESET}{GREEN}{text}")
}
fn error_prefix() -> String {
    format!("{RESET}\\x1b[1m\\x1b[31merror:{RESET}{RESET} ")
}
fn color_footer() -> String {
    format!(
        "\\n\\nFor more information try {}{}{RESET}",
        seg_green("--help"),
        seg_end()
    )
}

/// The (possibly coloured) error reported when stdin is not a tty.
pub fn stdin_must_be_tty_error() -> String {
    if color_enabled(std::io::stderr().is_terminal()) {
        format!(
            "{}{}{}\\n\\n{}{}{}",
            error_prefix(),
            seg_default("stdin must be a tty"),
            seg_end(),
            seg_default("USAGE:\\n    thokr [OPTIONS]"),
            seg_end(),
            color_footer()
        )
    } else {
        "error: stdin must be a tty\\n\\nUSAGE:\\n    thokr [OPTIONS]\\n\\nFor more information try --help\\n"
            .to_owned()
    }
}''')

# print_help / print_version with colour
old='''    fn print_help(&self) -> ! {
        exit_with(0, &self.help_text(), false)
    }

    fn print_version(&self) -> ! {
        exit_with(0, &format!("{} 0.4.1\\n", self.display), false)
    }
'''
new='''    fn print_help(&self) -> ! {
        if self.color_stdout {
            exit_with(0, &self.colored_help_text(), false)
        } else {
            exit_with(0, &self.help_text(), false)
        }
    }

    fn print_version(&self) -> ! {
        if self.color_stdout {
            exit_with(
                0,
                &format!("{RESET}{} 0.4.1\\n{RESET}", self.display),
                false,
            )
        } else {
            exit_with(0, &format!("{} 0.4.1\\n", self.display), false)
        }
    }

    fn colored_help_text(&self) -> String {
        let mut s = String::new();
        s.push_str(&RESET.repeat(3));
        s.push_str(&seg_green(&self.display));
        s.push_str(&seg_end());
        s.push(' ');
        s.push_str(&seg_default("0.4.1"));
        s.push_str(&seg_end());
        s.push('\\n');
        s.push_str(&seg_end());
        s.push_str(&seg_default(
            "sleek typing tui with visualized results and historical logging",
        ));
        s.push_str(&seg_end());
        s.push('\\n');
        s.push_str(&seg_end());
        s.push('\\n');
        s.push_str(&seg_yellow("USAGE:"));
        s.push_str(&seg_end());
        s.push_str("\\n    ");
        s.push_str(&seg_default(&format!("{} [OPTIONS]", self.bin)));
        s.push_str(&seg_end());
        s.push_str("\\n\\n");
        s.push_str(&seg_yellow("OPTIONS:"));
        s.push('\\n');
        let options: [(&str, &str, Option<&str>, &[&str]); 7] = [
            (
                "-f",
                "--full-sentences",
                Some("<NUMBER_OF_SENTENCES>"),
                &["number of sentences to use in test"],
            ),
            ("-h", "--help", None, &["Print help information"]),
            (
                "-l",
                "--supported-language",
                Some("<SUPPORTED_LANGUAGE>"),
                &[
                    "language to pull words from [default: english] [possible values: english, english1k,",
                    "english10k]",
                ],
            ),
            ("-p", "--prompt", Some("<PROMPT>"), &["custom prompt to use"]),
            (
                "-s",
                "--number-of-secs",
                Some("<NUMBER_OF_SECS>"),
                &["number of seconds to run test"],
            ),
            ("-V", "--version", None, &["Print version information"]),
            (
                "-w",
                "--number-of-words",
                Some("<NUMBER_OF_WORDS>"),
                &["number of words to use in test [default: 15]"],
            ),
        ];
        let last = options.len() - 1;
        for (i, (short, long, value, description)) in options.iter().enumerate() {
            s.push_str(&seg_default("    "));
            s.push_str(&seg_green(short));
            s.push_str(&seg_end());
            s.push_str(", ");
            s.push_str(&seg_green(long));
            s.push_str(&seg_end());
            if let Some(v) = value {
                s.push(' ');
                s.push_str(&seg_green(v));
                s.push_str(&seg_end());
            }
            for (j, line) in description.iter().enumerate() {
                if j == 0 {
                    s.push_str("\\n            ");
                    s.push_str(&seg_default(line));
                } else {
                    s.push('\\n');
                    s.push_str(&seg_default("            "));
                    s.push_str(&seg_default(line));
                }
                s.push_str(&seg_end());
            }
            if i == last {
                s.push_str(&seg_end());
                s.push_str(&seg_end());
                s.push('\\n');
                s.push_str(RESET);
            } else {
                s.push('\\n');
                s.push_str(&seg_end());
                s.push('\\n');
            }
        }
        s
    }
'''
