import pty,os,time,select,fcntl,termios,struct,signal,shutil
def run(prog,wait_before=0.37,secs=3):
 shutil.rmtree('/tmp/ptyhome',ignore_errors=True);os.makedirs('/tmp/ptyhome')
 pid,fd=pty.fork()
 if pid==0:
  os.environ['TERM']='xterm';os.environ['HOME']='/tmp/ptyhome';os.execv(prog,[prog,'-p','hello world','-s',str(secs)])
 fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack('HHHH',24,80,0,0));start=time.time();sent=False;events=[]
 while time.time()-start<wait_before+secs+1:
  if not sent and time.time()-start>=wait_before:os.write(fd,b'h');sent=True
  r,_,_=select.select([fd],[],[],.005)
  if fd in r:
   d=os.read(fd,65536);events.append((round(time.time()-start,3),d))
 try:os.kill(pid,9);os.waitpid(pid,0)
 except:pass
 return events
for prog in ['/tmp/refbin/executable','/tmp/mybin/executable']:
 ev=run(prog);print(prog);print([t for t,d in ev]);print([d for t,d in ev[2:5]])
PY
python3 /tmp/pty_timer_compare.py"}

